// ── Parity Task 19 (R-IOS-25): the Core's spots in a remote window ────────
//
// NereusSDR-original. The Core sends its spots as the `spots` record stream
// (SpotSourceHost::spotRecordFields) and its cluster consoles as
// spotConsole:<source>. A remote window shows the Core's spots in its own
// SpotModel (the panadapter overlay) and Spot List, beside its own WSJT-X and
// SpotCollector spots, under indices of its own. Colour and lifetime follow
// each source's Spot Hub settings, which are the Core's (Station scope).

namespace {

struct StationSpotLook {
    const char* colourKey;
    const char* colourDefault;
    const char* lifetimeKey;
    int lifetimeDefault;
};

// The per-source keys and defaults the on*SpotReceived slots above read.
StationSpotLook stationSpotLook(const QString& source)
{
    if (source == QLatin1String("RBN")) {
        return {"RbnSpotColor", "#4488FF", "RbnSpotLifetimeSec", 1800};
    }
    if (source == QLatin1String("POTA")) {
        return {"PotaSpotColor", "#FFFF00", "PotaSpotLifetimeSec", 1800};
    }
    if (source == QLatin1String("PSK")) {
        return {"PskReporterSpotColor", "#FF00FF", "PskReporterSpotLifetimeSec", 1800};
    }
    if (source == QLatin1String("FreeDV")) {
        return {"FreeDvSpotColor", "#FF8C00", "FreeDvSpotLifetimeSec", 1800};
    }
    if (source == QLatin1String("SpotCollector")) {
        return {"SpotCollectorSpotColor", "#B0C4DE", "SpotCollectorSpotLifetimeSec", 1800};
    }
    return {"DxClusterSpotColor", "#D2B48C", "DxClusterSpotLifetimeSec", 1800};
}

} // namespace

void RadioModel::applyStationRecordBatch(const RecordBatch& batch)
{
    // Remote-window parity Task 22 (R-R3-49): the Core's log, newest last.
    // A reset (each subscribe) replaces it.
    if (batch.stream == QLatin1String("coreLog")) {
        if (batch.reset) {
            m_stationCoreLog.clear();
        }
        for (const RecordUpsert& u : batch.upserts) {
            m_stationCoreLog.append(u.fields.value(QStringLiteral("line")).toString());
        }
        while (m_stationCoreLog.size() > kStationCoreLogLines) {
            m_stationCoreLog.removeFirst();
        }
        emit stationCoreLogChanged();
        return;
    }
    // Parity Task 23 (stationTciVersion 2): the apps on the Core's TCI
    // server, in the Core's order (they connected in the order of their
    // ids).
    if (batch.stream == QLatin1String("tciClients")) {
        QList<StationTciClient> clients =
            batch.reset ? QList<StationTciClient>{} : m_stationTciModel->clients();
        for (const QString& id : batch.removes) {
            clients.removeIf([&id](const StationTciClient& c) { return c.id == id; });
        }
        for (const RecordUpsert& u : batch.upserts) {
            const std::optional<StationTciClient> client =
                StationTciClient::fromFields(u.id, u.fields);
            if (!client) {
                continue;
            }
            const auto at = std::find_if(clients.begin(), clients.end(),
                                         [&u](const StationTciClient& c) { return c.id == u.id; });
            if (at != clients.end()) {
                *at = *client;
            } else {
                clients.append(*client);
            }
        }
        std::stable_sort(clients.begin(), clients.end(),
                         [](const StationTciClient& a, const StationTciClient& b) {
            return a.id.toULongLong() < b.id.toULongLong();
        });
        m_stationTciModel->setClients(clients);
        return;
    }
    // R-IOS-13 / R-R3-49 (txModMonitorVersion 1): the Core's AM Mod
    // Monitor readings, one record per source; a reset or a remove means
    // the Core sends none now.
    const int modMonitorSource = ModMonitorRecord::sourceOfStream(batch.stream);
    if (modMonitorSource >= 0) {
        auto& held = m_stationModMonitor[static_cast<std::size_t>(modMonitorSource)];
        if (batch.reset || !batch.removes.isEmpty()) {
            held.reset();
        }
        for (const RecordUpsert& u : batch.upserts) {
            if (u.id == QLatin1String(ModMonitorRecord::kRecordId)) {
                held = ModMonitorRecord::fromFields(u.fields);
            }
        }
        return;
    }
    // Parity Task 21 (R-IOS-18): the Core's radios, in the Core's order.
    if (batch.stream == QLatin1String("stationRadios")) {
        QList<StationRadioEntry> entries = batch.reset ? QList<StationRadioEntry>{}
                                                       : m_stationRadioEntries;
        for (const QString& id : batch.removes) {
            entries.removeIf([&id](const StationRadioEntry& e) { return e.id == id; });
        }
        for (const RecordUpsert& u : batch.upserts) {
            const std::optional<StationRadioEntry> entry =
                StationRadioEntry::fromFields(u.id, u.fields);
            if (!entry) {
                continue;
            }
            const auto at = std::find_if(entries.begin(), entries.end(),
                                         [&u](const StationRadioEntry& e) { return e.id == u.id; });
            if (at != entries.end()) {
                *at = *entry;
            } else {
                entries.append(*entry);
            }
        }
        // The Core's radio first.
        std::stable_sort(entries.begin(), entries.end(),
                         [](const StationRadioEntry& a, const StationRadioEntry& b) {
            return a.inUse && !b.inUse;
        });
        if (entries != m_stationRadioEntries) {
            m_stationRadioEntries = entries;
            emit stationRadiosChanged();
        }
        return;
    }
    // iPhone plan Task 22 / parity Task 20 (stationFreedvVersion 1): the
    // Core's FreeDV Reporter list, with the Core's distance and heading.
    if (batch.stream == QLatin1String("freedvStations")) {
        if (!m_freeDvStationModel) {
            return;
        }
        if (batch.reset) {
            m_freeDvStationModel->clear();
        }
        for (const QString& id : batch.removes) {
            m_freeDvStationModel->onStationRemoved(id);
        }
        for (const RecordUpsert& u : batch.upserts) {
            m_freeDvStationModel->applyStationRecord(u.id, u.fields);
        }
        return;
    }
    if (batch.stream.startsWith(QLatin1String("spotConsole:"))) {
        const QString source = batch.stream.mid(12);
        if (!SpotSourceHost::isStationSource(source) || !m_spotSourceHost) {
            return;
        }
        QStringList lines;
        for (const RecordUpsert& u : batch.upserts) {
            lines.append(u.fields.value(QStringLiteral("line")).toString());
        }
        // Fix wave, M5: a reset (each subscribe, a reconnect) carries the
        // Core's backlog again, so it replaces the console rather than
        // adding to it.
        m_spotSourceHost->appendStationConsole(source, lines, batch.reset);
        return;
    }
    if (batch.stream != QLatin1String("spots") || !m_spotModel) {
        return;
    }
    if (batch.reset) {
        // Fix wave, I3: the Core's spots only; its radio list is another
        // stream.
        clearStationSpots();
    }
    for (const QString& id : batch.removes) {
        const auto it = m_stationSpotIndex.find(id);
        if (it != m_stationSpotIndex.end()) {
            m_spotModel->removeSpot(it.value());
            m_stationSpotIndex.erase(it);
        }
    }
    auto& s = AppSettings::instance();
    for (const RecordUpsert& u : batch.upserts) {
        const QJsonObject& f = u.fields;
        const QString source = f.value(QStringLiteral("source")).toString();
        const StationSpotLook look = stationSpotLook(source);
        const double mhz = f.value(QStringLiteral("frequencyHz")).toDouble() / 1.0e6;
        const QDateTime when = QDateTime::fromString(f.value(QStringLiteral("timeUtc")).toString(),
                                                     Qt::ISODate);
        QMap<QString, QString> kvs;
        kvs[QStringLiteral("callsign")] = f.value(QStringLiteral("call")).toString();
        // Spot resolved mode (R-IOS-25): the Core's whole hertz, so a click
        // here resolves the mode a click at the Core does, even at a band
        // segment's edge.
        kvs[QStringLiteral("rx_freq")] = QString::number(mhz, 'f', 6);
        kvs[QStringLiteral("tx_freq")] = QString::number(mhz, 'f', 6);
        const QString mode = f.value(QStringLiteral("mode")).toString();
        if (!mode.isEmpty()) {
            kvs[QStringLiteral("mode")] = mode;
        }
        kvs[QStringLiteral("source")] = source;
        kvs[QStringLiteral("spotter_callsign")] = f.value(QStringLiteral("spotter")).toString();
        kvs[QStringLiteral("comment")] = f.value(QStringLiteral("comment")).toString();
        kvs[QStringLiteral("timestamp")] = QString::number(
            when.isValid() ? when.toSecsSinceEpoch() : QDateTime::currentSecsSinceEpoch());
        kvs[QStringLiteral("lifetime_seconds")] = QString::number(
            s.value(QString::fromLatin1(look.lifetimeKey), look.lifetimeDefault).toInt());
        kvs[QStringLiteral("color")] =
            s.value(QString::fromLatin1(look.colourKey), QString::fromLatin1(look.colourDefault))
                .toString();
        kvs[QStringLiteral("priority")] =
            QString::number(f.value(QStringLiteral("dxccPriority")).toInt());
        const bool isNew = !m_stationSpotIndex.contains(u.id);
        if (isNew) {
            m_stationSpotIndex.insert(u.id, m_spotModel->mintIndex());
        }
        m_spotModel->applySpotStatus(m_stationSpotIndex.value(u.id), kvs);
        // The Spot List lists each spot once, as a local source's arrival
        // does.
        if (isNew && m_spotTableModel) {
            DxSpot row;
            row.dxCall = kvs.value(QStringLiteral("callsign"));
            row.freqMhz = mhz;
            row.spotterCall = kvs.value(QStringLiteral("spotter_callsign"));
            row.comment = kvs.value(QStringLiteral("comment"));
            row.utcTime = when.isValid() ? when.toUTC().time() : QDateTime::currentDateTimeUtc().time();
            row.source = source;
            m_spotTableModel->addSpot(row);
        }
    }
}

QList<StationRadioEntry> RadioModel::stationRadios() const
{
    return m_stationRadioEntries;
}

void RadioModel::reportStationRadioRefused(const QString& reason)
{
    emit stationRadioRefused(reason);
}

void RadioModel::clearStationRecords()
{
    // Parity Task 23: a remote window's list of the Core's TCI apps.
    if (m_role == Role::Remote && m_stationTciModel) {
        m_stationTciModel->setClients({});
    }
    clearStationRadios();
    clearStationSpots();
    clearStationFreedv();
    clearStationModMonitor();
    if (!m_stationCoreLog.isEmpty()) {
        m_stationCoreLog.clear();
        emit stationCoreLogChanged();
    }
    if (m_role == Role::Remote && !m_remoteLogCategories.isEmpty()) {
        m_remoteLogCategories.clear();
        emit logCategoriesChanged(m_remoteLogCategories);
    }
}

// ── Remote-window parity Task 22 (R-R3-49): the Core's log and bundle ────────
//
// NereusSDR-original; no Thetis equivalent (Thetis has no remote window).

QString RadioModel::logCategories() const
{
    if (m_role == Role::Remote) {
        return m_remoteLogCategories;
    }
    return LogManager::instance().enabledList();
}

QString RadioModel::logCategoryList() const
{
    // Phone wire batch: the categories this process keeps, as the Support
    // dialog lists them.
    return LogManager::instance().categoryListJson();
}

QString RadioModel::stationSupportUnavailableReason() const
{
    if (m_station == nullptr || !m_station->stationLinkReady()) {
        return QStringLiteral("Connect to the Core to see its log.");
    }
    if (!m_station->supportBundleAvailable()) {
        return IStationLink::supportBundleUnavailableReason();
    }
    return {};
}

void RadioModel::noteStationSupportAvailabilityChanged()
{
    // A new session: the viewers that hold the Core's log follow it again.
    if (m_stationCoreLogViewers > 0 && m_station != nullptr) {
        m_station->requestCoreLog(true);
    }
    emit stationSupportAvailabilityChanged();
}

void RadioModel::addStationCoreLogViewer()
{
    if (++m_stationCoreLogViewers == 1 && m_station != nullptr) {
        m_station->requestCoreLog(true);
    }
}

void RadioModel::removeStationCoreLogViewer()
{
    if (m_stationCoreLogViewers == 0) {
        return;
    }
    if (--m_stationCoreLogViewers == 0 && m_station != nullptr) {
        m_station->requestCoreLog(false);
    }
}

void RadioModel::refreshStationCoreLog()
{
    if (m_stationCoreLogViewers > 0 && m_station != nullptr) {
        m_station->requestCoreLog(true);
    }
}

void RadioModel::reportStationSupportBundle(quint32 commandId, bool accepted,
                                            const QString& reason, const QByteArray& bundle)
{
    emit stationSupportBundleFinished(commandId, accepted, reason, bundle);
}

void RadioModel::reportStationLogCategoriesRefused(const QString& reason)
{
    emit stationLogCategoriesRefused(reason);
}

void RadioModel::clearStationFreedv()
{
    // Only a remote window's list is the Core's.
    if (m_role == Role::Remote && m_freeDvStationModel
        && m_freeDvStationModel->stationCount() > 0) {
        m_freeDvStationModel->clear();
    }
}

void RadioModel::clearStationRadios()
{
    if (!m_stationRadioEntries.isEmpty()) {
        m_stationRadioEntries.clear();
        emit stationRadiosChanged();
    }
    if (m_role == Role::Remote) {
        setStationRadioWaiting(QString());
    }
}

void RadioModel::setStationRadioWaiting(const QString& reason)
{
    if (m_stationRadioWaiting == reason) {
        return;
    }
    m_stationRadioWaiting = reason;
    emit stationRadioWaitingChanged(reason);
}

void RadioModel::clearStationSpots()
{
    if (m_spotModel) {
        for (const int index : std::as_const(m_stationSpotIndex)) {
            m_spotModel->removeSpot(index);
        }
    }
    m_stationSpotIndex.clear();
}

// ── Phase 3J-2 + 3R M3: spot-client auto-start state restore ───────────────
//
// Reads each per-source AutoConnect / AutoStart key from AppSettings and,
// when True, calls the corresponding start method with the persisted
// identity / port / interval params. MainWindow invokes this once at
// startup after RadioModel is fully wired (sibling to tryAutoReconnect
// for the radio connection itself).
//
// Key shape mirrors SpotHubDialog F2 (flat PascalCase, e.g.
// DxClusterAutoConnect / DxClusterHost / DxClusterPort / DxClusterCallsign).
// FreeDV Reporter identity / server URL is already plumbed by RadioModel's
// constructor (RadioModel.cpp:936-953); the restore here only needs to
// flip the WebSocket on. PSK Reporter is send-only; restore is a no-op.
//
// NereusSDR-original. AetherSDR splits this work between MainWindow's
// startup and per-source dialog handlers; the NereusSDR shape consolidates
// the read-and-start loop onto RadioModel so MainWindow's startup path
// stays a single call site.
void RadioModel::restoreSpotClientAutoStartState()
{
    // Remote-daemon R2 Task 5: gated to Role::Local. This is a safety
    // measure, not an ownership decision -- it exists only to stop a
    // Role::Remote GUI process from independently dialing every
    // auto-start-enabled spot source at startup, duplicating whatever
    // the daemon side also does: two DX cluster logins, two PSK Reporter
    // uploads under one callsign. Which side SHOULD own each collector
    // (client vs. station) is an open question this task does not
    // settle -- see docs/architecture/2026-08-03-remote-daemon-r2-open-
    // issues.md and this task's verification README paragraph for the
    // per-source breakdown. Do not read this gate as having decided
    // that question; it has not.
    //
    // Parity Task 19 (R-IOS-25) settles the question for the spot sources:
    // the station's (DX cluster, RBN, POTA, PSK Reporter) run on the Core
    // (restoreStationSpotSources), and each computer runs its own WSJT-X
    // and SpotCollector listeners, so a remote window starts those alone.
    if (role() != Role::Local) {
        m_spotSourceHost->restoreAutoStart(SpotSourceHost::Placement::WindowSources);
        return;
    }

    // Post-3J-2 UX fix: identity fall-back chain. The SpotHub Settings
    // tab writes a canonical User/Callsign + User/GridSquare pair; each
    // source first checks its own key, then the canonical one, and a
    // source that needs an identity skips its auto-start with none
    // (SpotSourceHost's resolveCall / resolveGrid, since parity Task 19).

    // Parity Task 19: every source starts through the spot source host,
    // with the same settings and calls as before. FreeDV Reporter too,
    // since iPhone plan Task 22: its identity is resolved from the saved
    // settings first and a start with none is skipped, as this function
    // did.
    m_spotSourceHost->restoreAutoStart(SpotSourceHost::Placement::Everything);
}

void RadioModel::restoreStationSpotSources()
{
    // Parity Task 19 (R-IOS-25): the Core's own settings; no window needed.
    m_spotSourceHost->restoreAutoStart(SpotSourceHost::Placement::StationSources);
}

bool RadioModel::isConnected() const
{
    // Storage-backed as of remote-daemon R2 Task 3 (was `m_connection &&
    // m_connection->isConnected()`). A remote client that deliberately owns
    // no RadioConnection (a StateMirror-driven GUI, from R2 onward) needs
    // isConnected() to be settable from stored state alone, not derived
    // from a pointer that will never exist on that side. m_connectionState
    // is already the single source of truth connectionState() exposes
    // (RadioModel.h:1433) and the sole thing setConnectionState() writes
    // (:11743-11758), so this is a change of derivation, not of meaning.
    // See docs/architecture/2026-08-03-remote-daemon-r2-r3-design-addendum.md
    // section 5.
    return m_connectionState == ConnectionState::Connected;
}

void RadioModel::setStepAttController(StepAttenuatorController* c)
{
    // Phase 4 Agent 4A of issue #167 — propagate to TransmitModel so the
    // ATT-on-TX safety gate inside setPowerUsingTargetDbm has a live
    // controller pointer.  Mirrors the existing m_stepAttController setter
    // pattern; non-owning on both sides.
    //
    // From Thetis console.cs:46740-46748 [v2.10.3.13]:
    //   //[2.10.3.5]MW0LGE max tx attenuation when power is increased and PS is enabled
    //   if (new_pwr != _lastPower && chkFWCATUBypass.Checked && _forceATTwhenPowerChangesWhenPSAon)
    //   { ... SetupForm.ATTOnTX = 31; ... }
    //
    // The PS-active gate (chkFWCATUBypass.Checked equivalent) is dormant
    // until 3M-4 PureSignal lands; until then the structure is in place
    // but the gate never fires (TransmitModel::pureSignalActive() returns
    // false unconditionally per Phase 3A).
    m_stepAttController = c;
    m_transmitModel.setStepAttenuatorController(c);
    // R-R3-46: the mirrored `stepAtt` object follows the Core's controller.
    // A Remote model's facade holds the Core's values instead, so a remote
    // window's own (radio-less) controller is never bound to it.
    if (m_role == Role::Local) {
        m_stepAttFacade->bindController(c);
    }

    // 2026-05-22 spectrum-calibration fix: rxMeterOffsetDb() depends on
    // the StepAttenuatorController state (preamp mode + step-att enable +
    // attenuator dB). Wire the three controller signals through to a
    // recompute-and-emit lambda so subscribers (MeterPoller, the spectrum
    // widget's dbmCalOffset) refresh whenever any of those change. Without
    // this the spectrum was stuck at whatever offset was current at startup
    // and never tracked preamp / step-att changes.
    //
    // Idempotent first-emit guard: only emit when the computed offset
    // actually changed from the cached value, so we don't fire redundant
    // updates on every controller tick.
    if (c) {
        auto recompute = [this]() { refreshRxMeterOffset(); };
        // The 6 m LNA gain offset (Setup > Calibration) is part of it too.
        connect(&m_calController, &CalibrationController::changed,
                this, &RadioModel::refreshRxMeterOffset, Qt::UniqueConnection);
        connect(c, &StepAttenuatorController::attenuationChanged,
                this, [recompute](int) { recompute(); });
        connect(c, &StepAttenuatorController::preampModeChanged,
                this, [recompute](PreampMode) { recompute(); });
        connect(c, &StepAttenuatorController::stepAttEnabledChanged,
                this, [recompute](bool) { recompute(); });
        // R-R3-46 / R-R3-11: the other ADC's attenuator, its preamp and
        // which ADC carries which attenuator move that ADC's offset.
        connect(c, &StepAttenuatorController::rx2AttenuationChanged,
                this, [this](int) { emit rxAdcMeterOffsetsChanged(); });
        connect(c, &StepAttenuatorController::rx1PreampChanged,
                this, [this](bool) { emit rxAdcMeterOffsetsChanged(); });
        connect(c, &StepAttenuatorController::rx2PreampModeChanged,
                this, [this](PreampMode) { emit rxAdcMeterOffsetsChanged(); });
        connect(c, &StepAttenuatorController::rx2StepAttEnabledChanged,
                this, [this](bool) { emit rxAdcMeterOffsetsChanged(); });
        connect(c, &StepAttenuatorController::adcRoutingChanged,
                this, &RadioModel::rxAdcMeterOffsetsChanged);
        // Initial emit so subscribers seed their cache with the current
        // value rather than waiting for the first controller change.
        recompute();
    }
}

// R-R3-46 / R-R3-11: each band remembers its attenuator and preamp, with a
// local radio and on the Core (DaemonApp calls this too). The attenuator
// belongs to the receive ADC, so its band is the receive band of slice A
// (slice 0), the RX1 equivalent; the ATT-on-TX value and the CW check on
// MOX follow the transmit-bound slice's band and mode, as Thetis keeps
// _tx_band and the TX DSP mode apart from rx1_band. Re-fed on every band or
// mode change of either slice and when the transmit binding moves.
// StepAttenuatorController::setBand saves the old band's values, restores
// the new band's and (setBandRestoreToRadio) sends them to the radio.
// From Thetis console.cs:17325 [v2.10.3.15] (RX1Band setter):
//   SetupForm.ATTOnTX = getTXstepAttenuatorForBand(_tx_band); //[2.10.3.6]MW0LGE att_fixes
//   RX1PreampMode = rx1_preamp_by_band[(int)rx1_band];
//   RX1AttenuatorData = getRX1stepAttenuatorForBand(rx1_band);
//   //[2.10.3.6]MW0LGE this tmp is needed because RX1AGCMode causes an update to the setup form
// From Thetis console.cs:29612-29616 [v2.10.3.15] (MOX, the CW check reads
// the transmit DSP mode):
//   //MW0LGE [2.9.0.7] added option to always apply 31 att from setup form when not in ps
//   int txAtt = getTXstepAttenuatorForBand(_tx_band);
//   ... (radio.GetDSPTX(0).CurrentDSPMode == DSPMode.CWL ||
//        radio.GetDSPTX(0).CurrentDSPMode == DSPMode.CWU)) txAtt = 31; // reset when PS is OFF or in CW mode
namespace {
// Slice A: the receiver whose band the step attenuator follows (Thetis RX1).
constexpr int kStepAttReceiveSliceId = 0;
} // namespace

void RadioModel::followReceiveSliceWithStepAttenuator()
{
    // A remote window's values are the Core's: the Core restores and sends.
    if (m_role != Role::Local || !m_stepAttController || m_stepAttFollowsSlices) {
        return;
    }
    m_stepAttFollowsSlices = true;
    m_stepAttController->setBandRestoreToRadio(true);

    auto wireSlice = [this](SliceModel* slice) {
        if (!slice) {
            return;
        }
        const auto drives = [this, slice] {
            return slice->sliceIndex() == kStepAttReceiveSliceId || slice == txBoundSlice();
        };
        connect(slice, &SliceModel::bandChanged, this, [this, drives](Band) {
            if (drives()) {
                syncStepAttenuatorToReceiveSlice();
            }
        });
        connect(slice, &SliceModel::dspModeChanged, this, [this, drives](DSPMode) {
            if (drives()) {
                syncStepAttenuatorToReceiveSlice();
            }
        });
        // R-R3-46 / R-R3-11: any slice can be the one controlling the other
        // ADC's attenuator; its band, its DDC and diversity move it.
        connect(slice, &SliceModel::bandChanged, this,
                [this](Band) { syncStepAttenuatorAdcRouting(); });
        connect(slice, &SliceModel::ddcIndexChanged, this,
                [this](int) { syncStepAttenuatorAdcRouting(); });
        connect(slice, &SliceModel::diversityEnabledChanged, this,
                [this](bool) { syncStepAttenuatorAdcRouting(); });
    };
    for (SliceModel* const slice : m_slices) {
        wireSlice(slice);
    }
    connect(this, &RadioModel::sliceAdded, this, [this, wireSlice](int index) {
        wireSlice(sliceById(index));
        if (index == kStepAttReceiveSliceId) {
            syncStepAttenuatorToReceiveSlice();
        }
    });
    if (m_txSliceArbiter) {
        connect(m_txSliceArbiter, &TxSliceArbiter::txBoundSliceChanged, this,
                [this](int, int) { syncStepAttenuatorToReceiveSlice(); });
    }
    // R-R3-46 / R-R3-11: a slice leaving, or a stream moving to the other
    // ADC, moves which attenuator an ADC carries.
    connect(this, &RadioModel::sliceRemoved, this,
            [this](int) { syncStepAttenuatorAdcRouting(); });
    connect(this, &RadioModel::streamAdcRoutingChanged, this,
            &RadioModel::syncStepAttenuatorAdcRouting);
    syncStepAttenuatorToReceiveSlice();
}

void RadioModel::syncStepAttenuatorToReceiveSlice()
{
    if (m_role != Role::Local || !m_stepAttController) {
        return;
    }
    // Receive band first: setBand also resets the transmit band, which the
    // transmit-bound slice then sets.
    if (SliceModel* const receive = sliceById(kStepAttReceiveSliceId)) {
        m_stepAttController->setBand(receive->band());
        // The 6 m LNA gain offset follows the receive band.
        refreshRxMeterOffset();
    }
    if (SliceModel* const tx = txBoundSlice()) {
        m_stepAttController->setTxBand(tx->band());
        m_stepAttController->setCurrentDspMode(tx->dspMode());
    }
    syncStepAttenuatorAdcRouting();
}

// R-R3-46 / R-R3-11: which ADC carries which step attenuator. Thetis sends
// RX1's to the ADC RX1 uses and RX2's to the ADC RX2 uses (GetADCInUse,
// console.cs:15110-15133 [v2.10.3.15]); see StepAttenuatorController.h.
// Slice A is RX1. The other ADC in use is RX2's, controlled by the
// lowest-numbered slice on it: Thetis has two receivers, so it has no rule
// for a third, and the lowest slice is the one that stands in for RX2 the
// way slice A stands in for RX1. Diversity (slice A only, both ADCs mixed)
// links the two, with slice A's band.
void RadioModel::syncStepAttenuatorAdcRouting()
{
    if (m_role != Role::Local || !m_stepAttController) {
        return;
    }
    const auto receiveAdc = [](int adc) { return adc == 0 || adc == 1; };
    const SliceModel* const sliceA = sliceById(kStepAttReceiveSliceId);
    int rx1Adc = sliceAdcIndex(kStepAttReceiveSliceId);
    if (!receiveAdc(rx1Adc)) {
        rx1Adc = 0;
    }
    int rx2Adc = -1;
    Band rx2Band = sliceA ? sliceA->band() : Band::GEN;
    int rx2SliceId = std::numeric_limits<int>::max();
    for (const SliceModel* const slice : std::as_const(m_slices)) {
        if (!slice || slice->sliceIndex() == kStepAttReceiveSliceId
            || slice->sliceIndex() >= rx2SliceId) {
            continue;
        }
        const int adc = sliceAdcIndex(slice->sliceIndex());
        if (receiveAdc(adc) && adc != rx1Adc) {
            rx2Adc = adc;
            rx2Band = slice->band();
            rx2SliceId = slice->sliceIndex();
        }
    }
    const bool linked = diversityActive() && boardCapabilities().adcCount >= 2;
    if (linked && rx2Adc < 0) {
        rx2Adc = rx1Adc == 0 ? 1 : 0;
    }
    // Every slice on the other ADC reads and sets its value.
    quint32 rx2SliceMask = 0;
    if (rx2Adc >= 0 && !linked) {
        for (const SliceModel* const slice : std::as_const(m_slices)) {
            if (slice && slice->sliceIndex() >= 0 && slice->sliceIndex() < 32
                && sliceAdcIndex(slice->sliceIndex()) == rx2Adc) {
                rx2SliceMask |= (1u << slice->sliceIndex());
            }
        }
    }
    m_stepAttController->setAdcRouting(rx1Adc, rx2Adc, rx2Band, linked, rx2SliceMask);
}

// R-R3-22: moved from MainWindow's existing PGXL/SmartSDR wiring. A
// headless Core has no window, and the viewed slice is not necessarily TX.
// Thetis console.cs:31889-31893,32865-32869 [v2.10.3.15] selects the TX VFO.
// No RF action is added here; existing frequency/mode wire forms are retained.
void RadioModel::rebindAccessorySlice()
{
    QObject::disconnect(m_accessoryFrequencyConnection);
    QObject::disconnect(m_accessoryModeConnection);
    QObject::disconnect(m_accessoryBandConnection);
    if (m_accessoryBandTimer) { m_accessoryBandTimer->stop(); }
    if (m_role != Role::Local || !m_smartSdrListener) { return; }
    SliceModel* const bound = txBoundSlice();
    if (!bound) { return; }
    m_smartSdrListener->setSliceFrequencyHz(0, bound->frequency());
    m_smartSdrListener->setSliceMode(0, SliceModel::modeName(bound->dspMode()));
    m_accessoryFrequencyConnection = connect(bound, &SliceModel::frequencyChanged,
        this, [this, bound](qint64 hz) {
            if (txBoundSlice() != bound) { return; }
            m_smartSdrListener->setSliceFrequencyHz(0, hz);
            m_accessoryBandTimer->start();
        });
    m_accessoryModeConnection = connect(bound, &SliceModel::dspModeChanged,
        this, [this, bound](DSPMode mode) {
            if (txBoundSlice() == bound) {
                m_smartSdrListener->setSliceMode(0, SliceModel::modeName(mode));
            }
        });
    m_accessoryBandConnection = connect(bound, &SliceModel::bandChanged,
        this, [this, bound](Band) {
            if (txBoundSlice() == bound) { publishAccessoryBand(); }
        });
    publishAccessoryBand();
}

// The HL2 I/O board poll takes the TX VFO's DSP mode and frequency
// (P1RadioConnection::ioBoardPollTick, REG_OP_MODE and REG_TX_FREQ_BYTE*).
// From mi0bot Console/console.cs:25835-25842, 25904-25915 [@c26a8a4]: the frequency of
// the VFO selected for transmit, (long)(VFOAFreq * 1000000.0), and its mode
// (_rx1_dsp_mode, or _rx2_dsp_mode on VFO B). Here the transmit-bound
// slice is that VFO.
void RadioModel::rebindIoBoardSlice()
{
    QObject::disconnect(m_ioBoardFrequencyConnection);
    QObject::disconnect(m_ioBoardModeConnection);
    auto* p1 = qobject_cast<P1RadioConnection*>(m_connection);
    if (m_role != Role::Local || p1 == nullptr) {
        return;
    }
    SliceModel* const bound = txBoundSlice();
    if (bound == nullptr) {
        return;
    }
    const auto push = [p1](int mode, qint64 hz) {
        QMetaObject::invokeMethod(p1, [p1, mode, hz]() { p1->setIoBoardTxState(mode, hz); });
    };
    push(static_cast<int>(bound->dspMode()), static_cast<qint64>(bound->frequency()));
    m_ioBoardFrequencyConnection = connect(bound, &SliceModel::frequencyChanged, this,
        [this, bound, push](double hz) {
            if (txBoundSlice() == bound) {
                push(static_cast<int>(bound->dspMode()), static_cast<qint64>(hz));
            }
        });
    m_ioBoardModeConnection = connect(bound, &SliceModel::dspModeChanged, this,
        [this, bound, push](DSPMode mode) {
            if (txBoundSlice() == bound) {
                push(static_cast<int>(mode), static_cast<qint64>(bound->frequency()));
            }
        });
}

void RadioModel::publishAccessoryBand()
{
    if (m_role != Role::Local || !fourO3AEnabled()
        || !m_pgxlConnection || !m_pgxlConnection->isConnected()) { return; }
    if (SliceModel* const bound = txBoundSlice()) {
        m_pgxlConnection->setBand(static_cast<int>(bound->frequency()));
    }
}

// ── 4O3A master toggle (Settings -> CAT & Network -> 4O3A General tab) ──────
//
// Persists per-MAC under hardware/<mac>/peripherals/FourO3A_Enabled
// (True / False string).  Default OFF on first run so the TCP 4992 port
// is not bound until the operator opts in.  Live-applies: starts/stops
// the SmartSdrApiListener immediately so the UI toggle doesn't require
// an app restart.
//
// No-op when no radio is connected (no MAC scope to write under).  The
// Setup page grays out under the same condition so the operator can't
// reach this entry point.
void RadioModel::setFourO3AEnabled(bool enabled)
{
    if (m_role == Role::Remote || currentRadioMac().isEmpty()) { return; }
    const bool changed = fourO3AEnabled() != enabled;
    if (changed) {
        setPeripheralValue(QStringLiteral("FourO3A_Enabled"),
                           enabled ? QStringLiteral("True") : QStringLiteral("False"));
        AppSettings::instance().save();
    }
    // Even repeated requests reconcile actual state: enable retries a failed
    // bind; disable unconditionally cancels a pending accessory attempt.
    if (!m_smartSdrListener) {
        return;  // ctor should always create it; defensive null guard
    }

    if (enabled) {
        if (!m_smartSdrListener->isListening()) {
            if (m_smartSdrListener->start()) {
                qCInfo(lcConnection) << "4O3A enabled: SmartSDR API listener"
                                      << "started on TCP 4992";
            } else {
                qCWarning(lcConnection) << "4O3A enabled: SmartSDR API listener"
                                         << "failed to bind TCP 4992";
            }
        }
    } else {
        m_smartSdrListener->stop(); // Also clears a prior failed-bind observation.
        if (m_accessoryBandTimer) { m_accessoryBandTimer->stop(); }
        qCInfo(lcConnection) << "4O3A disabled: SmartSDR API listener stopped";

        // Tear down any live PGXL / TGXL TCP socket. Without this, an
        // already-connected PGXL keeps sending statusUpdated frames,
        // m_hasAmplifier stays true, and the S-Meter keeps showing the
        // 2 kW PGXL scale even though the operator just disabled 4O3A.
        if (m_stationPgxl) {
            m_stationPgxl->cancel(true);
        } else if (m_pgxlConnection) {
            m_pgxlConnection->disconnect();
            qCInfo(lcConnection) << "4O3A disabled: PGXL TCP disconnected";
        }
        if (m_stationTgxl) {
            m_stationTgxl->cancel(true);
        } else if (m_tgxlConnection) {
            m_tgxlConnection->disconnect();
            qCInfo(lcConnection) << "4O3A disabled: TGXL TCP disconnected";
        }

        // Reset amp-presence cache. m_hasAmplifier is sticky-true after
        // any PGXL statusUpdated (see onPgxlStatus); resetting it here
        // lets the SMeterWidget / TunerApplet revert their power scales
        // to barefoot via the amplifierChanged(false) + ampStateChanged
        // emissions below. m_ampOperate also clears so STANDBY/OPERATE
        // consumers see the amp gone.
        if (m_hasAmplifier || m_ampOperate) {
            m_hasAmplifier = false;
            const bool wasOperate = m_ampOperate;
            m_ampOperate = false;
            emit amplifierChanged(false);
            if (wasOperate) { emit ampStateChanged(); }
        }
    }

    // R-R3-22: the FlexRadio beacon invites an amplifier or tuner to the
    // 4992 listener, so it runs only while 4O3A is on.
    updateFlexBeacon();

    emit fourO3AEnabledChanged(enabled);
    emit fourO3AStatusChanged();
}

bool RadioModel::fourO3AEnabled() const
{
    if (m_role == Role::Remote) { return m_remoteFourO3AEnabled; }
    return peripheralValue(QStringLiteral("FourO3A_Enabled"),
                           QStringLiteral("False"))
        == QStringLiteral("True");
}

bool RadioModel::fourO3AListening() const
{
    return m_role == Role::Remote ? m_remoteFourO3AListening
        : m_smartSdrListener && m_smartSdrListener->isListening();
}

QString RadioModel::fourO3AListenerError() const
{
    return m_role == Role::Remote ? m_remoteFourO3AListenerError
        : m_smartSdrListener ? m_smartSdrListener->lastListenError() : QString{};
}

bool RadioModel::setFourO3AEnabledForStation(bool enabled, QString* reason)
{
    if (m_role != Role::Local || !m_stationTgxl || currentRadioMac().isEmpty()) {
        if (reason) { *reason = QStringLiteral("Connect the Core to a radio before turning 4O3A on or off."); }
        return false;
    }
    setFourO3AEnabled(enabled);
    if (reason) { reason->clear(); }
    return true; // Persisted intent; actual bind success is a separate observation.
}

void RadioModel::clearRemoteFourO3AState()
{
    if (m_role != Role::Remote) { return; }
    const bool wasEnabled = m_remoteFourO3AEnabled;
    m_remoteFourO3AEnabled = false;
    m_remoteFourO3AListening = false;
    m_remoteFourO3AListenerError.clear();
    if (wasEnabled) { emit fourO3AEnabledChanged(false); }
    emit fourO3AStatusChanged();
}

void RadioModel::enableStationAccessoryIdentity()
{
    if (m_role != Role::Local || m_stationTgxl) { return; }
    m_stationTgxl = new StationTgxlController(m_tgxlConnection, m_tunerModel, this);
    m_stationTgxl->cancel(!fourO3AEnabled());
    // R-R3-47: the Tuner Genius's faults, recorded on the Core.
    connect(m_stationTgxl, &StationTgxlController::faultObserved, this,
            [this](const QString& kind, const QString& text, const QString& detail) {
        m_tgxlFaultLog->captureNotice(kind, text, detail);
    });
    // R-R3-47: the Power Genius, likewise identified before it is admitted
    // (and so before onPgxlConnected pairs it).
    m_stationPgxl = new StationPgxlController(m_pgxlConnection, m_amplifierModel, this);
    m_stationPgxl->cancel(!fourO3AEnabled());
    // R-R3-47 / R-R3-22: the amp's and tuner's own settings for a window.
    m_stationPgxl->deviceSettings()->setModel(m_accessorySettingsModel);
    m_stationTgxl->deviceSettings()->setModel(m_accessorySettingsModel);
    // R-R3-47: the RF-Kit too: admitted once its /info names an RF2K-S.
    m_stationRfKit = new StationRfKitController(m_rfKitConnection.get(), m_rfKitModel, this);
    m_stationRfKit->cancel(!rfKitEnabled());
    if (m_stationTciModel) {
        connect(m_stationTciModel, &StationTciModel::stateChanged, m_stationRfKit, [this] {
            if (m_stationRfKit) {
                m_stationRfKit->setBandFollowWanted(m_stationTciModel->listening());
            }
        });
    }
    applyStationBind();
}

void RadioModel::enableStationTci(const QString& bindOverride)
{
    if (m_role != Role::Local || m_stationTci) { return; }
    m_stationTci = std::make_unique<StationTciController>(this, m_stationTciModel);
    m_stationTci->setBindOverride(bindOverride);
    if (isConnected() && !m_lastRadioInfo.address.isNull()) {
        m_stationTci->setRadioAddress(m_lastRadioInfo.address);
    }
    // R-R3-48: the RF-Kit follows the band as an app of this server.
    m_rfKitBandFollow = std::make_unique<RfKitBandFollow>(m_rfKitModel);
    m_rfKitBandFollow->setServer(m_stationTci->server());
    // R-R3-22: the one station rule, when the Core has set it, wins over
    // the override given here.
    applyStationBind();
    m_stationTci->applySaved();
}

void RadioModel::setStationBind(const QString& bindOverride)
{
    if (m_role != Role::Local) { return; }
    StationNetwork::StationBind bind = m_stationBind.value_or(StationNetwork::StationBind{});
    bind.bindOverride = bindOverride.trimmed();
    m_stationBind = bind;
    applyStationBind();
}

void RadioModel::setStationInterfaceEntriesForTest(const QList<QNetworkAddressEntry>& entries)
{
    if (!m_stationBind) { return; }
    m_stationBind->entriesForTest = entries;
    applyStationBind();
}

void RadioModel::applyStationBind()
{
    if (!m_stationBind) { return; } // A desktop window: listeners bind as before.
    // The radio's address, kept across a disconnect so listeners stay on
    // the network they faced; null until a radio has connected.
    m_stationBind->radio = m_lastRadioInfo.address;
    const StationNetwork::StationBind& bind = *m_stationBind;
    if (m_stationTci) {
        if (bind.entriesForTest) {
            m_stationTci->setInterfaceEntriesForTest(*bind.entriesForTest);
        }
        m_stationTci->setBindOverride(bind.bindOverride);
        m_stationTci->setRadioAddress(bind.radio);
    }
    if (m_smartSdrListener) { m_smartSdrListener->setStationBind(bind); }
    if (m_stationPgxl) { m_stationPgxl->setStationBind(bind); }
    if (m_stationTgxl) { m_stationTgxl->setStationBind(bind); }
    if (m_flexBroadcaster) {
        // Announce the address the 4992 listener listens on; with no
        // single station address the beacon finds its own as before.
        const QHostAddress station = bind.stationAddress();
        const bool single = !station.isNull() && !bind.everyAddress() && !station.isLoopback();
        m_flexBroadcaster->setSourceAddress(single ? station : QHostAddress());
    }
}

void RadioModel::updateFlexBeacon()
{
    if (!m_flexBroadcaster) { return; }
    const bool broadcastSetting =
        AppSettings::instance().value(QStringLiteral("PGXL_BroadcastDiscovery"),
                                      QStringLiteral("True")).toString()
        == QStringLiteral("True");
    // R-R3-22: the beacon asks a Power Genius or Tuner Genius to connect to
    // the 4992 listener; with 4O3A off nothing listens there, so nothing is
    // announced.
    const bool wanted = m_role == Role::Local && m_flexBeaconConfigured
        && fourO3AEnabled() && broadcastSetting;
    if (wanted) {
        if (!m_flexBroadcaster->isRunning()) { m_flexBroadcaster->start(); }
    } else if (m_flexBroadcaster->isRunning()) {
        m_flexBroadcaster->stop();
    }
}

void RadioModel::configureFlexBeaconForTest()
{
    if (!m_flexBroadcaster) { return; }
    m_flexBroadcaster->setNoSendForTesting(true);
    m_flexBeaconConfigured = true;
    updateFlexBeacon();
}

bool RadioModel::flexBeaconRunningForTest() const
{
    return m_flexBroadcaster && m_flexBroadcaster->isRunning();
}

