bool RadioModel::setPgxlConnectionSettingsForStation(bool autoReconnect, int keepaliveSec,
                                                     int pingSec, QString* reason)
{
    const auto refuse = [reason](const QString& text) {
        if (reason) { *reason = text; }
        return false;
    };
    if (m_role != Role::Local || !m_stationPgxl) {
        return refuse(QStringLiteral("This Core cannot change its amplifier and tuner settings."));
    }
    if (keepaliveSec < kPgxlKeepaliveMinSec || keepaliveSec > kPgxlKeepaliveMaxSec
        || pingSec < 0 || pingSec > kPgxlPingMaxSec) {
        return refuse(QStringLiteral("Enter a keepalive of 1 to 3600 seconds and a ping of 0 to 3600 seconds."));
    }
    // Station-wide keys (SettingsScope "PGXL_"), saved together, then
    // applied to the running connection.
    auto& settings = AppSettings::instance();
    settings.setValue(QStringLiteral("PGXL_AutoReconnect"),
                      autoReconnect ? QStringLiteral("True") : QStringLiteral("False"));
    settings.setValue(QStringLiteral("PGXL_KeepaliveSec"), QString::number(keepaliveSec));
    settings.setValue(QStringLiteral("PGXL_PingSec"), QString::number(pingSec));
    settings.save();
    m_stationPgxl->applyConnectionSettings();
    if (reason) { reason->clear(); }
    return true;
}

bool RadioModel::isTransmitting() const
{
    // R-R3-49: a remote window holds the Core's value as it last heard it.
    if (m_role == Role::Remote) { return m_remoteTransmitting; }
    return m_transmitting;
}

bool RadioModel::transmitReleaseInProgress() const
{
    return m_role != Role::Remote && m_moxController != nullptr
        && m_moxController->isReleasing();
}

bool RadioModel::endOfOverTailActive() const
{
    return m_role != Role::Remote && m_moxController != nullptr
        && m_moxController->isEndOfOverTailActive();
}

// ---------------------------------------------------------------------------
// wireTxWorkerRade: the TX worker's RADE connections, made where the worker is
// created (and by installTxWorkerForTest).
//
// Phase 3R Task K2: mode-aware path swap on MOX-on. On every MOX-on
// transition, read the TX-bound slice's DSPMode and post a TxPath swap to the
// worker. DSPMode == RADE -> TxPath::Rade. Anything else -> TxPath::Wdsp (the
// existing path). The moxStateChanged signal fires exactly once per MOX
// transition at the END of the timer walk (MoxController.h:863-865
// [v2.10.3.13 conceptual]); the RX path doesn't need a corresponding TxPath
// flip because dispatchOneBlock is gated on the worker pump running anyway.
// The worker is the connection's context, so the connection goes with it
// (it used to capture the raw pointer with this model as context, and so
// outlived a worker a disconnect destroyed).
//
// RADE end-of-over callsigns: radeAudioDrained ends the tail.
// ---------------------------------------------------------------------------
void RadioModel::wireTxWorkerRade(TxWorkerThread* worker)
{
    if (worker == nullptr || m_moxController == nullptr) {
        return;
    }
    connect(m_moxController, &MoxController::moxStateChanged,
            worker, [this, worker](bool active) {
                // RADE threads (2026-09-30): the microphone reaches the RADE
                // encoder only while keyed; the path itself stays latched
                // for the end-of-over checks.
                worker->setRadeMicKeyed(active);
                if (!active) {
                    return;   // released; pump will idle anyway
                }
                const SliceModel* const txSlice = txBoundSlice();
                const DSPMode mode = txSlice ? txSlice->dspMode() : DSPMode::USB;
                const bool isRade = (mode == DSPMode::RADE_U || mode == DSPMode::RADE_L);
                worker->setCurrentTxPath(isRade ? TxWorkerThread::TxPath::Rade
                                                : TxWorkerThread::TxPath::Wdsp);
            });
    connect(worker, &TxWorkerThread::radeAudioDrained, this, [this]() {
        if (m_moxController) {
            m_moxController->onEndOfOverTailDone();
        }
    });
}

#ifdef NEREUS_BUILD_TESTS
void RadioModel::installTxWorkerForTest(std::unique_ptr<TxWorkerThread> worker)
{
    m_txWorker = std::move(worker);
    wireTxWorkerRade(m_txWorker.get());
}
#endif

// ---------------------------------------------------------------------------
// RADE end-of-over callsigns: the tail. NereusSDR-original sequencing of
// FreeDV's end of an over: once the operator lets go, the EOO frame (with
// the callsign rade_text encodes) and 200 ms of silence go out, then PTT
// drops (freedv-gui src/ongui.cpp:1479-1523 and
// src/pipeline/TxRxThread.cpp:808-847 [@a4ae053]; RadeChannel::
// queueEndOfOver carries the RADETransmitStep port).
//
// Only an operator's release: never after the Core's stops (the hold
// stopTransmitNow sets, or a closed RF gate), never for TUNE or two-tone,
// and only while the transmitter runs RADE on the TX-bound slice. The tail
// keys nothing: MOX is already off when this runs, the hardware simply
// stays keyed until the TX worker has taken the queued audio.
// ---------------------------------------------------------------------------
bool RadioModel::radeEndOfOverTailPermitted() const
{
    if (m_role == Role::Remote || m_transmitStopHold || m_refuseEndOfOverTail) {
        return false;
    }
    // Review Important 1: the path the TX worker latched when this key
    // began, not the slice's mode now. A slice switched to RADE while keyed
    // in another mode still has the live microphone on the WDSP path.
    if (!m_txWorker || m_txWorker->currentTxPath() != TxWorkerThread::TxPath::Rade) {
        return false;
    }
    if (m_txChannel == nullptr || !m_txChannel->isRfGateOpen()) {
        return false;
    }
    if (m_isTuning || m_pendingTuneOff || m_transmitModel.isTwoToneActive()) {
        return false;
    }
    // Review Minor 4: two-tone's own walk releases MOX before it keys (and
    // again when it stops); neither release ends an over.
    if (m_twoToneController
        && (m_twoToneController->isActive() || m_twoToneController->isActivationInFlight())) {
        return false;
    }
    const SliceModel* const txSlice = txBoundSlice();
    if (txSlice == nullptr) {
        return false;
    }
    const DSPMode mode = txSlice->dspMode();
    return mode == DSPMode::RADE_U || mode == DSPMode::RADE_L;
}

bool RadioModel::startRadeEndOfOverTail()
{
    if (!radeEndOfOverTailPermitted() || m_wdspEngine == nullptr) {
        return false;
    }
    SliceModel* const txSlice = txBoundSlice();
    RadeChannel* const channel = m_wdspEngine->radeChannel(txSlice->sliceIndex());
    if (channel == nullptr || !channel->isActive()) {
        return false;
    }
    // The callsign FreeDV Reporter registers with at the Core, and only
    // while the operator's FreeDV reporting is on, as FreeDV does:
    // From freedv-gui src/main.cpp:2643-2653 [@a4ae053]
    //   if (!wxGetApp().appConfiguration.reportingConfiguration.reportingEnabled)
    //   { freedvInterface.setTextCallbackFn(...); }
    //   else
    //   {
    //       strncpy(temp, ...reportingCallsign->ToUTF8(), 8); // One less than the size of temp to ensure we don't overwrite the null.
    //       freedvInterface.setReliableText(temp);
    //   }
    // With reporting off FreeDV never sets the EOO data: it creates no
    // rade_text object then (From freedv-gui src/freedv_interface.cpp:171-183
    // [@a4ae053]), so its end-of-over frame carries librade's zero data; an
    // empty callsign here writes the same zeros (RadeText::pushTxCallsign).
    //
    // FreeDV keys this on its reporting setting, not on the reporter's
    // connection. NereusSDR has no separate setting: reporting is on from
    // the operator's start (or the launch auto-start) until the operator
    // stops it, which is every reporter state but Off. A connection error
    // or a lost connection leaves it on, as the client keeps retrying.
    const bool reporting = m_spotSourceHost
        && m_spotSourceHost->freedvReporterState() != SpotSourceHost::kOff;
    const QString callsign = reporting ? SpotSourceHost::freedvCallsign() : QString();
    // queueEndOfOver emits txModemReady (the speech recorded before the
    // release, then the EOO) and runs the callback right after it, on this
    // thread; wireRadeChannel's lambda queues the samples to the worker, so
    // the notice below lands behind them. Fix wave (RADE EOO): with the
    // decoder holding the codec this happens once it lets go, not here;
    // MoxController's tail limit still bounds the wait.
    QPointer<RadioModel> self(this);
    return channel->queueEndOfOver(callsign, [self]() {
        if (self) {
            self->finishRadeEndOfOverTailQueue();
        }
    });
}

void RadioModel::finishRadeEndOfOverTailQueue()
{
    if (!m_txWorker) {
        return;
    }
    // Review Minor 1: the 24 -> 48 kHz stage holds back its latency too
    // (about 70 ms); push that much silence through it so the worker gets
    // all of the EOO and the 200 ms of silence behind it.
    if (m_radeTxResampler) {
        const std::vector<float> zeros(
            static_cast<size_t>(m_radeTxResampler->latencyInputSamples()), 0.0f);
        const QByteArray flushed =
            m_radeTxResampler->process(zeros.data(), static_cast<int>(zeros.size()));
        if (!flushed.isEmpty()) {
            QMetaObject::invokeMethod(m_txWorker.get(), "setRadeAudioBlock",
                                      Qt::QueuedConnection, Q_ARG(QByteArray, flushed));
        }
    }
    QMetaObject::invokeMethod(m_txWorker.get(), "armRadeAudioDrainedNotice",
                              Qt::QueuedConnection);
}

void RadioModel::dropRadeTxAudio()
{
    if (m_txWorker) {
        QMetaObject::invokeMethod(m_txWorker.get(), "clearRadeAudio",
                                  Qt::QueuedConnection);
    }
    m_radeTxResampler.reset();
    m_radeTxResamplerHwRate = 0;
    if (m_wdspEngine != nullptr) {
        if (SliceModel* const txSlice = txBoundSlice()) {
            if (RadeChannel* const channel = m_wdspEngine->radeChannel(txSlice->sliceIndex())) {
                channel->dropTxAudio();
            }
        }
    }
}

void RadioModel::onEndOfOverTailChanged(bool active)
{
    // Review Important 1: a mode change on the transmitting slice, or the
    // transmitter moving to another slice, ends the tail at once, so the
    // rest of the EOO never goes out through another mode's modulator.
    QObject::disconnect(m_endOfOverTailModeWatch);
    QObject::disconnect(m_endOfOverTailSliceWatch);
    if (active) {
        if (SliceModel* const txSlice = txBoundSlice()) {
            m_endOfOverTailModeWatch = connect(
                txSlice, &SliceModel::dspModeChanged, this, [this]() {
                    if (m_moxController) {
                        m_moxController->abortEndOfOverTail();
                    }
                });
        }
        if (m_txSliceArbiter) {
            m_endOfOverTailSliceWatch = connect(
                m_txSliceArbiter, &TxSliceArbiter::txBoundSliceChanged, this,
                [this](int, int) {
                    if (m_moxController) {
                        m_moxController->abortEndOfOverTail();
                    }
                });
        }
    }
    if (!active) {
        // The channel encodes the next over again.
        // Review Minor 5: a new key ended it. The end-of-over frame already
        // queued plays out whole ahead of the new over, as FreeDV's does:
        // RADETransmitStep::restartVocoder writes the EOO into the step's
        // output FIFO and execute reads that FIFO in order ahead of any
        // later modem samples, and freedv-gui drops PTT only once the EOO
        // is queued and the output has drained, so a new over never cuts
        // it (freedv-backend src/pipeline/RADETransmitStep.cpp:174-178,
        // 233, 242, 265 [@f02e7e9]; freedv-gui src/ongui.cpp:1479-1523
        // [@a4ae053]). Any other end (a stop, a block, a mode change, the
        // bound) drops what is left of it.
        const bool rekeyed = m_moxController != nullptr && m_moxController->isMox();
        if (m_txWorker && !rekeyed) {
            QMetaObject::invokeMethod(m_txWorker.get(), "clearRadeAudio",
                                      Qt::QueuedConnection);
        }
        if (m_wdspEngine != nullptr) {
            if (SliceModel* const txSlice = txBoundSlice()) {
                if (RadeChannel* const channel =
                        m_wdspEngine->radeChannel(txSlice->sliceIndex())) {
                    if (channel->endOfOverQueued()) {
                        channel->dropTxAudio();
                    }
                }
            }
        }
    }
    emit endOfOverTailChanged(active);
}

bool RadioModel::pureSignalOperationPermitted() const
{
    // R-R3-49 (parity Task 7, transmitSettingsVersion 7). Arming PureSignal
    // keys nothing: Single Cal, Automatic, Apply current correction and
    // Restore set the calibration engine's flags, and the engine corrects
    // only while the radio transmits. Thetis arms the same way, by flags,
    // from receive: AutoCalEnabled sets _autoON and PSState
    //   From Thetis PSForm.cs:272-289 [v2.10.3.15]
    // and the command state machine only then turns calibration on
    //   From Thetis PSForm.cs:644-648 [v2.10.3.15]
    //     puresignal.SetPSControl(_txachannel, 1, 0, 1, 0);
    //     if (!PSEnabled) PSEnabled = true;
    // (mi0bot-Thetis arms the HL2 the same way). So a receive-only Core
    // permits it: its session gate takes a window's arming only while the
    // radio is off the air, and its receive-only MOX check still keeps the
    // radio from transmitting, so the correction waits for a transmission.
    // A remote window never runs PureSignal itself; it asks its Core.
    return m_role != Role::Remote;
}

bool RadioModel::isCoreOnAir() const
{
    // R-R3-49 (parity Task 1): the Core's real MOX (`transmitting`), its
    // TUNE (the mirrored transmit model's), and PureSignal's two-tone.
    return isTransmitting() || m_transmitModel.isTune()
        || (m_pureSignalFacade && m_pureSignalFacade->twoToneOn());
}

void RadioModel::updateCoreOnAir()
{
    const bool now = isCoreOnAir();
    if (now != m_coreOnAir) {
        m_coreOnAir = now;
        emit coreOnAirChanged(now);
    }
}

void RadioModel::clearRemoteTransmittingState()
{
    if (m_role != Role::Remote) { return; }
    // PA on-air gate re-review, Important C: the Core's PA row too, so the
    // next Core (perhaps an older one that never sends it) starts from the
    // window's own fallback.
    if (m_stationPaTransmitBandKnown) {
        const int before = paOnAirBandIndex();
        m_stationPaTransmitBandKnown = false;
        m_stationPaTransmitBand = -1;
        if (paOnAirBandIndex() != before) {
            emit paTransmitBandChanged(paOnAirBandIndex());
            emit transmitBandChanged();
        }
    }
    // R-R3-49 (parity Task 6): the Core's TX inhibit too.
    if (m_remoteTxInhibited) {
        m_remoteTxInhibited = false;
        emit txInhibitedChanged(false);
    }
    // HL2 port part 2: and its reason.
    if (!m_txInhibitReason.isEmpty()) {
        m_txInhibitReason.clear();
        emit txInhibitReasonChanged(m_txInhibitReason);
    }
    if (!m_remoteTransmitting) { return; }
    m_remoteTransmitting = false;
    emit transmittingChanged(false);
}

bool RadioModel::isTxInhibited() const
{
    // R-R3-49 (parity Task 6): a remote window holds the Core's value.
    if (m_role == Role::Remote) { return m_remoteTxInhibited; }
    return m_txInhibit.inhibited();
}

QString RadioModel::txInhibitReason() const
{
    return m_txInhibitReason;
}

QString RadioModel::ioBoardFaultReason(quint8 code)
{
    // From mi0bot console.cs:25876-25885 [@c26a8a4]:
    //   infoBar.Warning("I/O Board: Fault Code " + ioBoard.readRegister(IOBoard.Registers.REG_FAULT).ToString());
    return QStringLiteral("I/O Board: Fault Code %1").arg(code);
}

void RadioModel::refreshTxInhibitReason()
{
    if (m_role == Role::Remote) {
        return;
    }
    const QString reason =
        m_txInhibit.inhibited()
                && m_txInhibit.lastSource() == safety::TxInhibitMonitor::Source::IoBoardFault
            ? ioBoardFaultReason(m_txInhibit.ioBoardFaultCode())
            : QString();
    if (reason == m_txInhibitReason) {
        return;
    }
    m_txInhibitReason = reason;
    emit txInhibitReasonChanged(reason);
}

RadioModel::PaReadings RadioModel::paReadings() const
{
    // R-R3-32 (parity Task 6): a remote window shows the Core's.
    if (m_role == Role::Remote) { return m_corePaReadings; }
    PaReadings readings;
    if (!isConnected() || m_connection == nullptr) { return readings; }
    // The connection's cached volts, -1 until a status frame reported them
    // (RadioConnection::lastUserAdc0Volts / lastSupplyVolts). The user ADC0
    // volts are reported only by the boards that sense their PA drain.
    const float paVolts = m_connection->lastUserAdc0Volts();
    if (paVolts >= 0.0f) { readings.paVolts = static_cast<double>(paVolts); }
    const float supplyVolts = m_connection->lastSupplyVolts();
    if (supplyVolts >= 0.0f) { readings.supplyVolts = static_cast<double>(supplyVolts); }
    // From Thetis clsHardwareSpecific.cs:255-264 [v2.10.3.15] HasAmps: only
    // the boards with a PA current sensor report amps.
    // //N1GP G2E added
    if (m_paCurrentReported && boardCapabilities().hasPaAmpsTelemetry) {
        readings.paCurrentAmps = m_radioStatus.paCurrentAmps();
    }
    if (m_paTemperatureReported) {
        readings.paTemperatureCelsius = m_radioStatus.paTemperatureCelsius();
    }
    return readings;
}

RadioModel::PaRowVolts RadioModel::paRowVolts() const
{
    const PaReadings readings = paReadings();
    PaRowVolts row;
    if (m_hardwareProfile.model == HPSDRModel::ANAN_G2E) {
        row.volts = readings.supplyVolts;
        row.supply = true;
    } else {
        row.volts = readings.paVolts;
    }
    return row;
}

void RadioModel::applyCorePaReadings(const PaReadings& readings)
{
    if (m_role != Role::Remote || readings == m_corePaReadings) { return; }
    m_corePaReadings = readings;
    emit paReadingsChanged();
}

bool RadioModel::rfKitEnabled() const
{
    // R-R3-47: a remote window holds the Core's switch as it last heard it.
    if (m_role == Role::Remote) { return m_remoteRfKitEnabled; }
    return peripheralValue(QStringLiteral("RfKit_Enabled"),
                           QStringLiteral("False"))
        == QStringLiteral("True");
}

// Push the operator's RF-Kit preferences into the live connection.
//
// Review blocker [P2] on PR #291: RfKitPage persisted RfKit_AutoReconnect
// and RfKit_PollIntervalMs to AppSettings, but nothing ever read them back.
// scheduleReconnect() retried unconditionally and the poll cadence stayed at
// the 1000 ms default, so both controls were inert -- the checkbox and the
// spinbox moved, saved, reloaded into the UI, and changed nothing.
//
// Called immediately before every connectToAmp() so the settings apply to
// both the Setup-toggle path and the per-MAC auto-connect path.
void RadioModel::applyRfKitOperatorSettings()
{
    if (!m_rfKitConnection) {
        return;
    }
    const bool autoRe = AppSettings::instance()
        .value(QStringLiteral("RfKit_AutoReconnect"), QStringLiteral("True"))
        .toString() == QStringLiteral("True");
    m_rfKitConnection->setAutoReconnect(autoRe);

    bool ok = false;
    const int pollMs = AppSettings::instance()
        .value(QStringLiteral("RfKit_PollIntervalMs"), QStringLiteral("1000"))
        .toString().toInt(&ok);
    if (ok) {
        // setPollIntervalMs clamps to 250..5000 itself.
        m_rfKitConnection->setPollIntervalMs(pollMs);
    }
}

void RadioModel::setRfKitEnabled(bool enabled)
{
    if (m_role == Role::Remote) {
        // R-R3-47: the switch lives on the Core; a remote window asks it
        // with the setRfKitEnabled command (IStationLink).
        qCWarning(lcConnection) << "setRfKitEnabled ignored in a remote window;"
                                << "the Core owns the RF-Kit switch";
        return;
    }
    const bool current = rfKitEnabled();
    if (enabled == current) {
        return;
    }
    setPeripheralValue(QStringLiteral("RfKit_Enabled"),
                       enabled ? QStringLiteral("True") : QStringLiteral("False"));

    if (enabled) {
        const QString host = peripheralValue(QStringLiteral("RfKit_ManualIp"));
        const quint16 port = static_cast<quint16>(
            peripheralValue(QStringLiteral("RfKit_ManualPort"),
                            QStringLiteral("8080")).toUInt());
        if (!host.isEmpty() && m_rfKitConnection) {
            applyRfKitOperatorSettings();
            if (m_stationRfKit) {
                m_stationRfKit->start(host, port);   // R-R3-47: identity first
            } else {
                m_rfKitConnection->connectToAmp(host, port);
            }
        } else if (m_stationRfKit) {
            m_stationRfKit->cancel(false);
        }
    } else if (m_stationRfKit) {
        m_stationRfKit->cancel(true);
    } else if (m_rfKitConnection) {
        m_rfKitConnection->disconnect();
    }

    emit rfKitEnabledChanged(enabled);
}

bool RadioModel::setRfKitEnabledForStation(bool enabled, QString* reason)
{
    if (m_role != Role::Local || !m_stationRfKit) {
        if (reason) { *reason = QStringLiteral("This Core cannot change its amplifier and tuner settings."); }
        return false;
    }
    if (currentRadioMac().isEmpty()) {
        if (reason) {
            *reason = QStringLiteral("Connect the Core to a radio before turning its RF-Kit "
                                     "amplifier on or off.");
        }
        return false;
    }
    setRfKitEnabled(enabled);
    AppSettings::instance().save();
    if (reason) { reason->clear(); }
    return true;
}

// R-R3-47 / R-R3-22: the Power Genius's configure rule for the RF-Kit.
// Acceptance is "saved and identifying"; `rfkit`.connectionPhase says
// whether it connected.
bool RadioModel::configureRfKitForStation(const QString& inputHost, quint16 port, QString* reason)
{
    const auto refuse = [reason](const QString& text) {
        if (reason) { *reason = text; }
        return false;
    };
    if (m_role != Role::Local || !m_stationRfKit) {
        return refuse(QStringLiteral("This Core cannot change its amplifier and tuner settings."));
    }
    if (currentRadioMac().isEmpty()) {
        return refuse(QStringLiteral("Connect the Core to a radio before setting up its RF-Kit "
                                     "amplifier."));
    }
    if (!rfKitEnabled()) {
        return refuse(QStringLiteral("Turn on the RF-Kit amplifier on the Core before "
                                     "connecting it."));
    }
    const QString host = inputHost.trimmed();
    if (!validStationAccessoryHost(host) || port == 0) {
        return refuse(QStringLiteral("Enter the RF-Kit amplifier's IP address or host name, "
                                     "and a port from 1 to 65535."));
    }
    // Both fields are saved by one accepted command, validated first.
    setPeripheralValue(QStringLiteral("RfKit_ManualIp"), host);
    setPeripheralValue(QStringLiteral("RfKit_ManualPort"), QString::number(port));
    AppSettings::instance().save();
    applyRfKitOperatorSettings();
    m_stationRfKit->start(host, port);
    if (reason) { reason->clear(); }
    return true;
}

bool RadioModel::disconnectRfKitForStation(QString* reason)
{
    if (m_role != Role::Local || !m_stationRfKit) {
        if (reason) { *reason = QStringLiteral("This Core cannot change its amplifier and tuner settings."); }
        return false;
    }
    m_stationRfKit->cancel(!rfKitEnabled());
    if (reason) { reason->clear(); }
    return true;
}

bool RadioModel::resetRfKitErrorForStation(QString* reason)
{
    if (m_role != Role::Local || !m_stationRfKit) {
        if (reason) { *reason = QStringLiteral("This Core cannot reset its RF-Kit amplifier's error."); }
        return false;
    }
    return m_stationRfKit->resetError(reason);
}

// ---------------------------------------------------------------------------
// R-R3-49 (parity Task 10, remoteRfKitControlVersion 4): a window's RF-Kit
// OPERATE, antenna, TCI mode and saved address. NereusSDR-original; no
// Thetis logic (the RF2K-S is a NereusSDR-native accessory).
// ---------------------------------------------------------------------------

bool RadioModel::stationRfKitControlAllowed(QString* reason) const
{
    if (m_role != Role::Local || !m_stationRfKit) {
        if (reason) { *reason = QStringLiteral("This Core cannot change its amplifier and tuner settings."); }
        return false;
    }
    return !stationOnAirRefusal(reason);
}

// Operating the amp keys nothing: it amplifies only when the radio
// transmits.
bool RadioModel::setRfKitOperateForStation(bool on, QString* reason)
{
    if (!stationRfKitControlAllowed(reason)) { return false; }
    return m_stationRfKit->setOperate(on, reason);
}

bool RadioModel::setRfKitAntennaForStation(int port, QString* reason)
{
    // The applet's four internal antenna buttons, ANT 1 to ANT 4.
    if (port < 1 || port > AccessoryDataModel::kRfKitAntennas) {
        if (reason) { *reason = QStringLiteral("Choose RF-Kit amplifier antenna 1, 2, 3 or 4."); }
        return false;
    }
    if (!stationRfKitControlAllowed(reason)) { return false; }
    return m_stationRfKit->setAntenna(port, reason);
}

bool RadioModel::setRfKitTciModeForStation(QString* reason)
{
    if (!stationRfKitControlAllowed(reason)) { return false; }
    return m_stationRfKit->setTciMode(reason);
}

// configureRfKit's checks and reasons, less the dial and the switch check
// (saving dials nothing). Parity mini-round (rulings a and b): saving
// switches nothing, so it goes ahead on the air, as a local window's Save
// does; OPERATE, the antennas and TCI mode above still wait.
bool RadioModel::setRfKitAddressForStation(const QString& inputHost, int port, QString* reason)
{
    const auto refuse = [reason](const QString& text) {
        if (reason) { *reason = text; }
        return false;
    };
    if (m_role != Role::Local || !m_stationRfKit) {
        return refuse(QStringLiteral("This Core cannot change its amplifier and tuner settings."));
    }
    if (currentRadioMac().isEmpty()) {
        return refuse(QStringLiteral("Connect the Core to a radio before setting up its RF-Kit "
                                     "amplifier."));
    }
    const QString host = inputHost.trimmed();
    // Group B fix wave (I1): a blank Host is saved, as a local window's
    // blank Host is, and stops auto-connect: applyPeripheralsForCurrentMac
    // dials only a saved host that is not empty.
    if ((!host.isEmpty() && !validStationAccessoryHost(host)) || port < 1 || port > 65535) {
        return refuse(QStringLiteral("Enter the RF-Kit amplifier's IP address or host name, "
                                     "and a port from 1 to 65535."));
    }
    setPeripheralValue(QStringLiteral("RfKit_ManualIp"), host);
    setPeripheralValue(QStringLiteral("RfKit_ManualPort"), QString::number(port));
    AppSettings::instance().save();
    m_stationRfKit->showSavedEndpoint(host, static_cast<quint16>(port));
    if (reason) { reason->clear(); }
    return true;
}

// ── Per-radio peripherals helpers ──────────────────────────────────────────
//
// Resolve the "current MAC" via m_lastRadioInfo.macAddress.  When empty
// (no radio connected, or a probe/discovery entry without MAC), peripheral
// reads return the caller's default and peripheral writes are a no-op +
// qCWarning.  Setup pages must gray themselves out under the same condition
// so the operator can't reach the write path with an unbound MAC.
QString RadioModel::currentRadioMac() const
{
    // Gated on the connection state, matching this accessor's documented
    // contract in RadioModel.h ("returns m_lastRadioInfo.macAddress when
    // connected, empty otherwise") -- the implementation had drifted from
    // its own documentation and returned the MAC unconditionally.
    //
    // m_lastRadioInfo is deliberately retained across a disconnect, so the
    // ungated version kept naming the previous radio forever.  RfKitPage
    // and FourO3APage both use a non-empty result as their live/enabled
    // gate, which let the operator edit -- and start -- peripherals scoped
    // to a radio that was no longer there.  Codex review, PR #291.
    //
    // Deliberately m_connectionState rather than isConnected(): the latter
    // requires a live RadioConnection object, and the Setup-page tests
    // drive state through setConnectionStateForTest() without one.
    // teardownPeripherals() reads no MAC, so nothing in the disconnect
    // path depends on the old behaviour.
    if (m_connectionState != ConnectionState::Connected) {
        return QString{};
    }
    return m_lastRadioInfo.macAddress;
}

QString RadioModel::peripheralValue(const QString& key,
                                    const QString& defaultValue) const
{
    const QString mac = currentRadioMac();
    if (mac.isEmpty()) {
        return defaultValue;
    }
    return AppSettings::instance()
        .hardwareValue(mac, QStringLiteral("peripherals/") + key, defaultValue)
        .toString();
}

void RadioModel::setPeripheralValue(const QString& key, const QString& value)
{
    const QString mac = currentRadioMac();
    if (mac.isEmpty()) {
        qCWarning(lcConnection)
            << "setPeripheralValue('" << key << "',...) ignored:"
            << "no radio connected; no MAC scope to write under";
        return;
    }
    AppSettings::instance().setHardwareValue(
        mac, QStringLiteral("peripherals/") + key, value);
}

// ── Per-radio peripherals lifecycle ─────────────────────────────────────────
//
// applyPeripheralsForCurrentMac runs when the radio reports Connected and
// m_lastRadioInfo.macAddress is populated.  Reads the per-MAC enable +
// host/port slots and dials out for each accessory that's switched On.
// teardownPeripherals runs on Disconnected / LinkLost and tears every
// live socket / TCP listener down so we never leave them attached to the
// previous radio's scope when the user switches to a different rig.
void RadioModel::applyPeripheralsForCurrentMac()
{
    // One-shot fold of legacy globals into the currently connected MAC's
    // scope.  Idempotent across launches via PeripheralsMigrationDone.
    migratePeripheralGlobalsIfNeeded();

    const QString mac = currentRadioMac();
    if (mac.isEmpty()) {
        qCWarning(lcConnection)
            << "applyPeripheralsForCurrentMac: no MAC available, skipping";
        return;
    }

    int started = 0;

    // R-R3-22 / R-R3-47: on the Core every station listener follows this
    // radio's network before any of them starts.
    applyStationBind();

    // ── 4O3A SmartSDR API listener on TCP 4992 ──────────────────────────
    // Must come before PGXL/TGXL because the live socket dials are gated
    // on the same per-MAC flag.
    const bool fourO3AOn = fourO3AEnabled();
    if (fourO3AOn) {
        if (m_smartSdrListener && !m_smartSdrListener->isListening()) {
            if (m_smartSdrListener->start()) {
                qCInfo(lcConnection) << "4O3A SmartSDR API listener started"
                                      << "for MAC" << mac;
                ++started;
            } else {
                qCWarning(lcConnection)
                    << "4O3A enabled but TCP 4992 bind failed for MAC" << mac;
            }
        }
        // Re-emit fourO3AEnabledChanged so views that cache the value
        // refresh against the now-known per-MAC scope (the value may
        // differ from the previously connected radio).
        emit fourO3AEnabledChanged(true);
    } else {
        // A radio scope replacement can arrive without an intervening
        // enabled-state change. Never retain the previous scope's listener.
        if (m_smartSdrListener) { m_smartSdrListener->stop(); }
        if (!m_stationPgxl && m_pgxlConnection) { m_pgxlConnection->disconnect(); }
        emit fourO3AEnabledChanged(false);
    }
    // R-R3-22: this radio's 4O3A switch decides the FlexRadio beacon.
    updateFlexBeacon();

    emit fourO3AStatusChanged();

    // ── RF-Kit RF2K-S ───────────────────────────────────────────────────
    // R-R3-48: the Core's station TCI server faces this radio's network.
    if (m_stationTci && !m_lastRadioInfo.address.isNull()) {
        m_stationTci->setRadioAddress(m_lastRadioInfo.address);
    }
    // R-R3-47: publish this radio's saved RF-Kit address on the Core
    // before anything can dial it, as for the Power Genius below.
    if (m_stationRfKit) {
        const QString savedHost = peripheralValue(QStringLiteral("RfKit_ManualIp"));
        const quint16 savedPort = static_cast<quint16>(
            peripheralValue(QStringLiteral("RfKit_ManualPort"),
                            QStringLiteral("8080")).toUInt());
        m_stationRfKit->resetScope(savedHost, savedPort, rfKitEnabled());
    }
    if (rfKitEnabled() && m_rfKitConnection) {
        const QString host =
            peripheralValue(QStringLiteral("RfKit_ManualIp"));
        const quint16 port = static_cast<quint16>(
            peripheralValue(QStringLiteral("RfKit_ManualPort"),
                            QStringLiteral("8080")).toUInt());
        if (!host.isEmpty()) {
            applyRfKitOperatorSettings();
            if (m_stationRfKit) {
                m_stationRfKit->start(host, port);
            } else {
                m_rfKitConnection->connectToAmp(host, port);
            }
            qCInfo(lcConnection)
                << "RF-Kit auto-connect for MAC" << mac
                << ":" << host << ":" << port;
            ++started;
        } else {
            qCInfo(lcConnection)
                << "RF-Kit enabled for MAC" << mac
                << "but no host configured; skipping auto-connect";
        }
        emit rfKitEnabledChanged(true);
    } else {
        emit rfKitEnabledChanged(false);
    }

    // Publish the current radio's saved endpoint even when disabled or
    // unconfigured. Cancellation within a scope retains its draft; moving to
    // another MAC must replace it before any connection can start.
    const QString tgxlIp = peripheralValue(QStringLiteral("TGXL_ManualIp"));
    bool tgxlPortOk = false;
    const uint savedTgxlPort = peripheralValue(QStringLiteral("TGXL_ManualPort"),
        QStringLiteral("9010")).toUInt(&tgxlPortOk);
    const quint16 tgxlPort = tgxlPortOk && savedTgxlPort <= 65535
        ? quint16(savedTgxlPort) : 0;
    if (m_stationTgxl) {
        m_stationTgxl->resetScope(tgxlIp, tgxlPort, fourO3AOn);
    }
    // R-R3-47: the same for the Power Genius.
    const QString pgxlIp = peripheralValue(QStringLiteral("PGXL_ManualIp"));
    bool pgxlPortOk = false;
    const uint savedPgxlPort = peripheralValue(QStringLiteral("PGXL_ManualPort"),
        QStringLiteral("9008")).toUInt(&pgxlPortOk);
    const quint16 pgxlPort = pgxlPortOk && savedPgxlPort <= 65535
        ? quint16(savedPgxlPort) : 0;
    if (m_stationPgxl) {
        m_stationPgxl->resetScope(pgxlIp, pgxlPort, fourO3AOn);
    }

    // ── PGXL / TGXL (gated on 4O3A master) ──────────────────────────────
    // Without the 4O3A gate, a saved PGXL_ManualIp would dial out even
    // with 4O3A disabled, get a statusUpdated back, flip m_hasAmplifier
    // = true, and snap the S-Meter to the 2 kW PGXL scale -- surprising
    // the operator who explicitly turned 4O3A off (see MainWindow's
    // earlier auto-connect block where this gate was first established).
    if (fourO3AOn) {
        if (!pgxlIp.isEmpty() && m_pgxlConnection
            && !m_pgxlConnection->isConnected()) {
            const quint16 p = m_stationPgxl ? pgxlPort
                : static_cast<quint16>(peripheralValue(QStringLiteral("PGXL_ManualPort"),
                                                       QStringLiteral("9008")).toUInt());
            bool pgxlStarted = true;
            if (m_stationPgxl) {
                QString reason;
                if (!configurePgxlForStation(pgxlIp, p, &reason)) {
                    AmplifierModel::StationConnectionState state;
                    state.configuredHost = pgxlIp;
                    state.configuredPort = p;
                    state.phase = AmplifierModel::ConnectionPhase::Error;
                    state.error = reason;
                    m_amplifierModel->setStationConnectionState(state);
                    pgxlStarted = false;
                }
            } else {
                m_pgxlConnection->connectToPgxl(pgxlIp, p);
            }
            if (pgxlStarted) {
                qCInfo(lcConnection) << "PGXL auto-connect for MAC" << mac
                                      << ":" << pgxlIp << ":" << p;
                ++started;
            }
        }

        if (!tgxlIp.isEmpty() && m_tgxlConnection
            && !m_tgxlConnection->isConnected()) {
            const quint16 p = tgxlPort;
            if (m_stationTgxl) {
                QString reason;
                if (!configureTgxlForStation(tgxlIp, p, &reason)) {
                    TunerModel::StationConnectionState state;
                    state.configuredHost = tgxlIp;
                    state.configuredPort = p;
                    state.phase = TunerModel::ConnectionPhase::Error;
                    state.error = reason;
                    m_tunerModel->setStationConnectionState(state);
                    return;
                }
            } else {
                m_tgxlConnection->connectToTgxl(tgxlIp, p);
            }
            qCInfo(lcConnection) << "TGXL auto-connect for MAC" << mac
                                  << ":" << tgxlIp << ":" << p;
            ++started;
        }
    }

    if (started == 0) {
        qCInfo(lcConnection)
            << "No peripherals enabled for MAC" << mac;
    }
}

void RadioModel::teardownPeripherals()
{
    // Deliberately NOT gated on isConnected(). Review blocker [P1] on PR
    // #291: when the link has dropped and a reconnect is pending,
    // isConnected() is false, so the gate skipped disconnect() and left the
    // retry armed -- it would then fire after the operator disabled RF-Kit,
    // re-issue /info and restart polling. disconnect() is idempotent: it
    // stops both timers and only emits disconnected() if it had been
    // connected.
    if (m_stationRfKit) {
        m_stationRfKit->cancel(!rfKitEnabled());
        qCInfo(lcConnection) << "Peripherals teardown: RF-Kit disconnected";
    } else if (m_rfKitConnection) {
        m_rfKitConnection->disconnect();
        qCInfo(lcConnection) << "Peripherals teardown: RF-Kit disconnected";
    }
    if (m_smartSdrListener) {
        m_smartSdrListener->stop();
        qCInfo(lcConnection) << "Peripherals teardown: SmartSDR API stopped";
    }
    if (m_stationPgxl) {
        m_stationPgxl->cancel();
    } else if (m_pgxlConnection) {
        m_pgxlConnection->disconnect();
        qCInfo(lcConnection) << "Peripherals teardown: PGXL disconnected";
    }
    if (m_stationTgxl) {
        m_stationTgxl->cancel();
    } else if (m_tgxlConnection) {
        m_tgxlConnection->disconnect();
        qCInfo(lcConnection) << "Peripherals teardown: TGXL disconnected";
    }
    if (m_accessoryBandTimer) { m_accessoryBandTimer->stop(); }
    emit fourO3AStatusChanged();
}

void RadioModel::migratePeripheralGlobalsIfNeeded()
{
    auto& s = AppSettings::instance();
    if (s.value(QStringLiteral("PeripheralsMigrationDone"))
            .toString() == QStringLiteral("True")) {
        return;
    }
    const QString mac = currentRadioMac();
    if (mac.isEmpty()) {
        // Defer migration until we know a MAC.  Without a target scope
        // there's nowhere to write the folded values.
        return;
    }

    static constexpr const char* kKeys[] = {
        "RfKit_Enabled", "RfKit_ManualIp", "RfKit_ManualPort",
        "FourO3A_Enabled",
        "PGXL_ManualIp", "PGXL_ManualPort",
        "TGXL_ManualIp", "TGXL_ManualPort",
    };

    int migrated = 0;
    for (const char* k : kKeys) {
        const QString key = QString::fromLatin1(k);
        if (!s.contains(key)) {
            continue;
        }
        const QString v = s.value(key).toString();
        if (v.isEmpty()) {
            // Remove empty leftovers so they don't linger as ghost keys.
            s.remove(key);
            continue;
        }
        s.setHardwareValue(mac,
                           QStringLiteral("peripherals/") + key, v);
        s.remove(key);
        ++migrated;
    }

    s.setValue(QStringLiteral("PeripheralsMigrationDone"),
               QStringLiteral("True"));
    s.save();
    qCInfo(lcConnection)
        << "Peripherals migration: folded" << migrated
        << "global key(s) into hardware/" << mac << "/peripherals/";
}

bool RadioModel::isAnyExternalAmpInOperate() const
{
    // PGXL: explicit booleans set by PgxlConnection::statusUpdated handler.
    if (m_hasAmplifier && m_ampOperate) {
        return true;
    }
    // RF-Kit: poll the last-known operate_mode from Rf2ksConnection.  The
    // connection caches it in m_operateMode and refreshes once per second.
    // Require a live connection: m_operateMode is a cache with no
    // disconnect invalidation, so an amp last seen in OPERATE kept this
    // predicate true forever after it dropped, pinning MainWindow to the
    // 2 kW scale and suppressing the radio's barefoot power updates.
    // Codex review, PR #291.
    if (isRfKitInOperate()) {
        return true;
    }
    return false;
}

bool RadioModel::isRfKitInOperate() const
{
    // Same liveness requirement as the RF-Kit branch above: m_operateMode is
    // a cache with no disconnect invalidation, so an amp last seen in
    // OPERATE would otherwise read as amplifying forever after it dropped.
    return m_rfKitConnection
        && m_rfKitConnection->isConnected()
        && m_rfKitConnection->operateMode() == QStringLiteral("OPERATE");
}

int RadioModel::userStreamCount() const
{
    if (m_role == Role::Remote) {
        return m_stationUserDdcCount;
    }
    const BoardCapabilities& caps = boardCapabilities();
    if (m_lastRadioInfo.macAddress.isEmpty()) {
        return BoardCapsTable::userDdcCountFor(caps, caps.protocol);
    }
    return BoardCapsTable::userDdcCountFor(caps, m_lastRadioInfo.protocol,
                                           m_lastRadioInfo.reportedReceivers);
}

int RadioModel::receiverPoolCeiling(const RadioInfo& info, int poolStreams)
{
    if (info.protocol == ProtocolVersion::Protocol2) {
        return std::max(info.maxReceivers, poolStreams);
    }
    return info.maxReceivers;
}

int RadioModel::maxActiveRxCount() const
{
    if (!m_hardwareProfile.caps) {
        return 1;
    }
    return BoardCapsTable::effectiveReceiverCount(*m_hardwareProfile.caps,
                                                  m_lastRadioInfo.protocol,
                                                  m_lastRadioInfo.reportedReceivers);
}

const BoardCapabilities& RadioModel::boardCapabilities() const
{
#ifdef NEREUS_BUILD_TESTS
    if (m_testWidebandCaps) {
        return *m_testWidebandCaps;
    }
    if (m_testCapsOverride) {
        static BoardCapabilities overrideCaps{};
        overrideCaps.hasAlex     = m_testCapsHasAlex;
        overrideCaps.isRxOnlySku = m_testCapsIsRxOnly;  // 3M-1a G.2
        overrideCaps.hasMicJack  = m_testCapsHasMicJack; // 3M-1b I.1
        overrideCaps.board       = m_testCapsHw;          // 3M-1b I.3
        // 3M-1b I.4: propagate per-board mic gain range from the canonical
        // caps table for the injected board type.  This lets mic-gain range
        // tests observe the correct per-family values without a live radio.
        const BoardCapabilities& canonical = BoardCapsTable::forBoard(m_testCapsHw);
        overrideCaps.micGainMinDb = canonical.micGainMinDb;
        overrideCaps.micGainMaxDb = canonical.micGainMaxDb;
        return overrideCaps;
    }
#endif
    if (m_hardwareProfile.caps) { return *m_hardwareProfile.caps; }
    return BoardCapsTable::forBoard(HPSDRHW::Unknown);
}

// ── Phase 3F: maxSlices() accessor ──────────────────────────────────────────
//
// Returns 1 when disconnected (safe single-slice default so callers never
// see zero and attempt to create slices with no radio present).
//
// When connected, delegates to boardCapabilities().maxSlices for the active
// SKU.  A zero value there is also clamped to 1 — it signals that the
// BoardCapabilities row has not yet been populated for that SKU (Task 1-3),
// which should be treated as "at least one slice".
//
// NereusSDR-original — no Thetis upstream.
// Design: docs/architecture/2026-05-26-phase3f-multi-pan-multi-slice-design.md §2.
int RadioModel::maxSlices() const
{
    if (!isConnected()) {
        return 1;
    }
    // Remote-daemon R2 Task 18: a Role::Remote model gates on the
    // EFFECTIVE limit the station advertised, never on the board's own
    // BoardCapabilities::maxSlices -- parent design section 4.5, "Capacity
    // is a runtime property, not a SKU property ... The client gates its
    // UI on the effective values, never the board values." The two differ
    // whenever the daemon's own hardware cannot sustain what the radio
    // supports, which is the entire reason the effective number exists.
    //
    // Role::Local never reaches this branch, so local direct mode reads
    // exactly what it always did.
    if (m_role == Role::Remote) {
        return m_stationMaxSlices > 0 ? m_stationMaxSlices : 1;
    }
    const int n = boardCapabilities().maxSlices;
    return n > 0 ? n : 1;
}

// ── Remote-daemon R2 Task 18: production handshake entry points ─────────────
//
// See RadioModel.h's doc comments for why these exist at all (before this
// task the only non-connection writer of m_connectionState was a test seam)
// and why both refuse on a Role::Local model.

void RadioModel::applyStationCapabilities(const NereusSDR::StationCapabilities& caps)
{
    if (m_role != Role::Remote) {
        qCWarning(lcConnection)
            << "applyStationCapabilities ignored on a Role::Local model: a local"
            << "model's identity and connection state come from its own radio";
        return;
    }

    // Identity first. name/model/version are mirrored Q_PROPERTYs with no
    // WRITE, and RadioModel::applyMirroredValue refuses all three on
    // purpose (its own comment names this task as the path that fills
    // them), so this is their only remote writer.
    const bool infoMoved = m_name != caps.stationName || m_model != caps.radioModelName
        || m_version != caps.firmwareVersion;
    m_name = caps.stationName;
    m_model = caps.radioModelName;
    m_version = caps.firmwareVersion;

    // R-R3-46: what a listener of currentRadioChanged would see differently.
    const auto identityOf = [this]() {
        return std::make_tuple(m_lastRadioInfo.macAddress, m_lastRadioInfo.boardType,
                               m_lastRadioInfo.name, m_lastRadioInfo.firmwareVersion,
                               m_lastRadioInfo.protocol, m_lastRadioInfo.address,
                               m_hardwareProfile.model, m_hardwareProfile.effectiveBoard,
                               m_hardwareProfile.caps);
    };
    const auto identityBefore = identityOf();

    // The MAC is what scopes every hardware/<mac>/ settings read, so it has
    // to be the STATION's radio rather than anything this client saw.
    m_lastRadioInfo.macAddress = caps.macAddress;
    m_lastRadioInfo.boardType = caps.board;
    m_lastRadioInfo.name = caps.stationName;
    // R-R3-46: the rest of the stored radio info, so Protocol Info, Radio
    // Info and every currentRadioChanged listener read the Core's radio.
    // The Core sends its firmware as the number a local connect shows.
    bool firmwareOk = false;
    const int firmware = caps.firmwareVersion.trimmed().toInt(&firmwareOk);
    m_lastRadioInfo.firmwareVersion = firmwareOk && firmware > 0 ? firmware : 0;
    if (caps.radioProtocol == 2) {
        m_lastRadioInfo.protocol = ProtocolVersion::Protocol2;
    } else {
        // 1, or not reported: RadioInfo's own default.
        m_lastRadioInfo.protocol = ProtocolVersion::Protocol1;
    }
    m_lastRadioInfo.address = caps.radioAddress.isEmpty()
        ? QHostAddress() : QHostAddress(caps.radioAddress);

    // Board type drives boardCapabilities(), which 14 GUI sites read for
    // slider ranges, antenna counts and preamp tables. R-R3-46: the Core's
    // own model wins when it matches the board (an ANAN-8000DLE or ANAN-G2
    // 1K keeps its row); otherwise the same defaultModelForBoard() a local
    // connect uses picks it; and a Core with no radio (Unknown board) gives
    // Unknown, never Hermes.
    m_hardwareProfile = ::NereusSDR::profileForStation(caps.board, caps.hpsdrModel);
    m_calController.setHardwareModel(m_hardwareProfile.model);
    // Task 16: a Core running the HL2 receive-only kit shows receive only.
    applyRxOnly();
    // As a local connect does before its currentRadioChanged: display units
    // and clamps that depend on the model (HL2) read it from here.
    m_transmitModel.setHpsdrModel(m_hardwareProfile.model);
    const bool identityMoved = identityOf() != identityBefore;

    m_stationMaxSlices = caps.effectiveMaxSlices > 0 ? caps.effectiveMaxSlices : 1;
    m_stationUserDdcCount = caps.userDdcCount;
    const bool remoteIqMoved = m_stationRemoteIqVersion != caps.remoteIqVersion;
    m_stationRemoteIqVersion = caps.remoteIqVersion;
    // R-R3-49 (parity Task 16): whether the Core sends its filter curve,
    // and (trunk merge) whether it says which noise reduction it runs.
    setStationDspInfoVersion(caps.dspInfoVersion);
    // Parity Task 30: whether the Core applies TX Display's settings.
    setStationTxDisplayVersion(caps.txDisplayVersion);
    // Parity Task 33: whether the Core sends its transmit readings.
    setStationTxReadingsVersion(caps.txReadingsVersion);
    setStationDspAssetVersion(caps.dspAssetVersion);

    if (infoMoved || remoteIqMoved) {
        emit infoChanged();
    }

    // LAST, deliberately: connectionStateChanged() is what wakes every GUI
    // site that then re-reads maxSlices() and boardCapabilities(), so
    // emitting it before the values above are settled would hand those
    // sites the stale ones.
    setConnectionState(caps.radioConnected ? ConnectionState::Connected
                                           : ConnectionState::Disconnected);

    // R-R3-46: then the radio itself, once per change of identity, as a
    // local connect emits it after Connected with the profile already set.
    // Every listener reads the settled profile and state. A resent
    // descriptor for the same radio (a slice-limit change, a transmit
    // permission) wakes nothing.
    if (identityMoved) {
        emit currentRadioChanged(m_lastRadioInfo);
        // R-R3-46 (parity Task 6): the PA pages show this radio's bank.
        reloadRemotePaState();
    }
}

void RadioModel::setStationConnectionState(ConnectionState s)
{
    if (m_role != Role::Remote) {
        qCWarning(lcConnection)
            << "setStationConnectionState ignored on a Role::Local model: its"
            << "connection state has exactly one writer, its own RadioConnection";
        return;
    }
    setConnectionState(s);
}

int RadioModel::addSliceWithStationId(int sliceId, const QString& initialPanId)
{
    if (m_role != Role::Remote) {
        qCWarning(lcConnection)
            << "addSliceWithStationId ignored on a Role::Local model: local slice"
            << "ids are minted here, not handed in";
        return -1;
    }
    if (sliceId < 0) {
        return -1;
    }
    if (sliceById(sliceId) != nullptr) {
        // The station believes this id is new and this client believes it
        // is live. Refusing is the same call ObjectRegistry::onSliceAdded
        // makes for a duplicate create on the daemon side: clobbering the
        // existing slice would orphan whatever already references it.
        qCWarning(lcConnection) << "Station create for slice id" << sliceId
                                << "which this client already holds; refused";
        return -1;
    }
    return addSliceImpl(sliceId, initialPanId);
}

// ── Remote-daemon R2: the station's answers coming back ────────────────────
//
// See RadioModel.h for why these exist. All three are the inbound twins of
// the outbound command routing in addSlice / addSliceOnPan / removeSlice /
// setActiveSliceById / requestSliceSampleRate below, and all three refuse
// on a Role::Local model for the same reason applyStationCapabilities and
// setStationConnectionState do: a local model's slice list has exactly one
// authority, its own operator, and letting a second one in is how the two
// silently disagree.

void RadioModel::setStationDevices(RemoteDevicesState* devices)
{
    m_stationDevices = devices;
}

RemoteDevicesState* RadioModel::stationDevices() const
{
    return qobject_cast<RemoteDevicesState*>(m_stationDevices.data());
}

void RadioModel::removeSliceWithStationId(int sliceId)
{
    if (m_role != Role::Remote) {
        qCWarning(lcConnection)
            << "removeSliceWithStationId ignored on a Role::Local model: local"
            << "slices are removed by their own operator, not by a station";
        return;
    }
    removeSliceImpl(sliceId);
}

void RadioModel::applyStationActiveSlice(int sliceId)
{
    if (m_role != Role::Remote) {
        qCWarning(lcConnection)
            << "applyStationActiveSlice ignored on a Role::Local model: its active"
            << "slice is chosen here, not reported to it";
        return;
    }
    SliceModel* target = sliceById(sliceId);
    if (target == nullptr) {
        // Ordinary, not an error: an `active` delta can land in the same
        // batch as the create it belongs to, or name a slice this client
        // has already reaped. The create's own snapshot carries `active`
        // too, so nothing is lost by ignoring it here.
        return;
    }
    const int position = m_slices.indexOf(target);
    if (position < 0) {
        return;
    }
    // The LOCAL body, deliberately. Everything the daemon did when it made
    // this slice active (clear the previous flag, move m_activeSlice, emit
    // both the positional and the id-based signal) has to happen here too,
    // and setActiveSlice is where all of it already lives.
    setActiveSlice(position);
}

void RadioModel::reportStationSliceCommandRejected(const QString& reason)
{
    if (m_role != Role::Remote) {
        return;
    }
    emit sliceAddRejected(reason);
}

void RadioModel::reportStationAccessoryRefusal(const QString& device, const QString& reason,
                                               quint32 commandId)
{
    if (m_role != Role::Remote) {
        return;
    }
    // Rework part 5: shown only on a page still there and on screen.
    const QPointer<QObject> page = m_pageShownAccessoryRequests.take(commandId);
    const bool shownOnPage = commandId != 0 && page
        && page->property("visible").toBool();
    emit accessoryRequestRefused(device, reason, shownOnPage);
}

void RadioModel::noteAccessoryRequestShownOnPage(quint32 commandId, QObject* page)
{
    if (commandId != 0 && page) {
        m_pageShownAccessoryRequests.insert(commandId, page);
    }
}

void RadioModel::reportStationLinkStateChanged()
{
    // Rework part 5: with the link down no claimed answer will come.
    const IStationLink* link = stationLink();
    if (!link || !link->stationLinkReady()) {
        m_pageShownAccessoryRequests.clear();
    }
    emit stationLinkStateChanged();
}

// ── R-R3-49 (parity Task 5): SWR protection, applied when it changes ─────
//
// The defaults are the constructor's reads above (Phase 3M-0 Task 17).

bool RadioModel::isSwrProtectionSettingKey(const QString& key)
{
    return key == QLatin1String("SwrProtectionEnabled")
        || key == QLatin1String("SwrProtectionLimit")
        || key == QLatin1String("SwrTuneProtectionEnabled")
        || key == QLatin1String("TunePowerSwrIgnore")
        || key == QLatin1String("WindBackPowerSwr");
}

// ── Remote-window parity Task 16 (R-R3-49, R-R3-21, R-R3-40) ────────────────
//
// NereusSDR-original. The facts a remote window needs about its Core's DSP
// that it used to read from its own build or its own (idle) channels.

QString RadioModel::noiseReductionNotSaidReason()
{
    return QStringLiteral("This Core does not say which noise reduction it can run. "
                          "Updating the Core may help.");
}

void RadioModel::setStationDspInfoVersion(int version)
{
    if (m_role != Role::Remote) {
        return;
    }
    const QPointer<RadioModel> self(this);
    const bool changed = m_stationDspInfoVersion != version;
    m_stationDspInfoVersion = version;
    if (changed) {
        emit stationDspInfoVersionChanged();
        if (!self) { return; }
    }
    if (m_stationDspInfoVersion != version) { return; }
    if (m_coreFilterResponseWanted) {
        watchCoreFilterResponseSlice();
        requestCoreFilterResponse();
        if (!self) { return; }
    }
    QVector<QPair<int, quint64>> demands;
    demands.reserve(m_miniFilterResponses.size());
    for (auto it = m_miniFilterResponses.cbegin(); it != m_miniFilterResponses.cend(); ++it) {
        demands.append({it.key(), it->serial});
    }
    for (const auto& [sliceId, serial] : demands) {
        const auto current = m_miniFilterResponses.constFind(sliceId);
        if (current == m_miniFilterResponses.cend() || current->serial != serial
            || m_stationDspInfoVersion != version) { continue; }
        requestMiniFilterResponse(sliceId);
        if (!self) { return; }
    }
}

void RadioModel::setStationDspAssetVersion(int version)
{
    // Trunk merge of parity Tasks 16 to 18 (R-R3-49): a Core below
    // dspAssetVersion 3 never sends dfnrRunnable, below 4 never mnrRunnable;
    // nrCannotRunReason then says it does not say.
    if (m_role != Role::Remote || m_stationDspAssetVersion == version) {
        return;
    }
    m_stationDspAssetVersion = version;
    emit nrAvailabilityChanged();
}

qint64 RadioModel::dspOptionsLastApplyMs() const
{
    return m_dspOptionsLastApplyMs;
}

bool RadioModel::filterResponseForStation(int sliceId, bool highResolution,
                                          FilterResponse* out, QString* reason) const
{
    const auto refuse = [reason](const QString& text) {
        if (reason) {
            *reason = text;
        }
        return false;
    };
    SliceModel* slice = sliceById(sliceId);
    if (slice == nullptr) {
        return refuse(QStringLiteral("The Core has no such slice."));
    }
    FilterResponse response;
    if (highResolution) {
        // The filter graph's own computation (DspOptionsPage binds
        // FilterDisplayItem to the channel and it paints
        // filterResponseMagnitudes): the bins it resamples.
        RxChannel* channel = rxChannelForSlice(slice->sliceIndex());
        if (channel == nullptr) {
            return refuse(QStringLiteral("The Core's receiver for this slice is not running."));
        }
        double stepHz = 0.0;
        const QVector<double> bins = channel->filterResponseBins(&stepHz);
        if (bins.isEmpty()) {
            return refuse(QStringLiteral("The Core cannot work out this filter's curve."));
        }
        double peak = 0.0;
        for (double m : bins) {
            peak = std::max(peak, m);
        }
        peak = std::max(peak, 1e-30);
        response.stepHz = stepHz;
        response.magnitudesDb.reserve(bins.size());
        for (double m : bins) {
            // The graph's own floor (RxChannel::resampleFilterResponse).
            response.magnitudesDb.append(
                std::max(20.0 * std::log10(std::max(m, 1e-300) / peak), -120.0));
        }
    }
    if (out) {
        *out = response;
    }
    return true;
}

QString RadioModel::filterResponseToJson(const QVector<double>& magnitudesDb)
{
    QJsonArray array;
    for (double db : magnitudesDb) {
        array.append(std::round(db * 1000.0) / 1000.0);
    }
    return QString::fromUtf8(QJsonDocument(array).toJson(QJsonDocument::Compact));
}

std::optional<QVector<double>> RadioModel::filterResponseFromJson(const QString& json)
{
    QJsonParseError error{};
    const QJsonDocument doc = QJsonDocument::fromJson(json.toUtf8(), &error);
    if (error.error != QJsonParseError::NoError || !doc.isArray()) {
        return std::nullopt;
    }
    QVector<double> values;
    const QJsonArray array = doc.array();
    values.reserve(array.size());
    for (const QJsonValue& v : array) {
        if (!v.isDouble() || !std::isfinite(v.toDouble())) {
            return std::nullopt;
        }
        values.append(v.toDouble());
    }
    return values;
}

QString RadioModel::coreFilterResponseUnavailableReason() const
{
    if (m_role != Role::Remote) {
        return {};
    }
    if (m_stationDspInfoVersion < 1) {
        return IStationLink::filterResponseUnavailableReason();
    }
    return {};
}

SliceModel* RadioModel::coreFilterResponseSlice() const
{
    // A local window's graph draws channel 0 (DspOptionsPage's
    // filterGraphChannel); a remote window asks for the same receiver,
    // slice 0, or the active slice when there is none.
    if (SliceModel* first = sliceById(0)) {
        return first;
    }
    return m_activeSlice;
}

void RadioModel::watchCoreFilterResponseSlice()
{
    for (QMetaObject::Connection& conn : m_coreFilterResponseSliceConns) {
        disconnect(conn);
    }
    m_coreFilterResponseSliceConns.clear();
    if (m_role != Role::Remote || !m_coreFilterResponseWanted) {
        return;
    }
    SliceModel* slice = coreFilterResponseSlice();
    if (slice == nullptr) {
        return;
    }
    // The curve follows the channel's filter edges and rate; the minimum
    // notch width moves with the rate (nbp.c min_notch_width), so it stands
    // in for a rate change the window cannot see otherwise.
    const auto again = [this]() { requestCoreFilterResponse(); };
    m_coreFilterResponseSliceConns << connect(slice, &SliceModel::filterChanged, this, again)
                                   << connect(slice, &SliceModel::dspModeChanged, this, again)
                                   << connect(slice, &SliceModel::minNotchWidthHzChanged, this,
                                              again);
}

void RadioModel::setCoreFilterResponseWanted(bool wanted)
{
    if (m_role != Role::Remote) {
        return;
    }
    if (m_coreFilterResponseWanted == wanted) {
        return;
    }
    m_coreFilterResponseWanted = wanted;
    if (!wanted) {
        watchCoreFilterResponseSlice();
        return;
    }
    watchCoreFilterResponseSlice();
    requestCoreFilterResponse();
}

void RadioModel::requestCoreFilterResponse()
{
    if (m_role != Role::Remote || !m_coreFilterResponseWanted || m_station == nullptr
        || m_stationDspInfoVersion < 1) {
        return;
    }
    // One request at a time: a change while one is out asks again when it
    // is answered, so a filter drag sends no more than the Core answers.
    if (m_coreFilterResponseCommand != 0) {
        m_coreFilterResponseDirty = true;
        return;
    }
    SliceModel* slice = coreFilterResponseSlice();
    if (slice == nullptr) {
        return;
    }
    const IStationLink::CommandOutcome outcome =
        m_station->requestFilterResponse(slice->sliceIndex(), /*highResolution=*/true);
    if (!outcome.sent) {
        return;
    }
    m_coreFilterResponseDirty = false;
    m_coreFilterResponseCommand = outcome.commandId != 0 ? outcome.commandId : 1;
}

void RadioModel::setMiniFilterResponseSlices(const QSet<int>& sliceIds)
{
    if (m_role != Role::Remote) { return; }
    const QPointer<RadioModel> self(this);
    const quint64 setEpoch = ++m_miniFilterDemandSetEpoch;
    for (auto it = m_miniFilterResponses.begin(); it != m_miniFilterResponses.end();) {
        if (sliceIds.contains(it.key()) && sliceById(it.key())) { ++it; continue; }
        for (const auto& connection : it->connections) { disconnect(connection); }
        it = m_miniFilterResponses.erase(it);
    }
    for (int sliceId : sliceIds) {
        if (m_miniFilterDemandSetEpoch != setEpoch) { return; }
        if (m_miniFilterResponses.contains(sliceId)) { continue; }
        SliceModel* slice = sliceById(sliceId);
        if (!slice) { continue; }
        MiniFilterResponseState& state = m_miniFilterResponses[sliceId];
        state.serial = ++m_nextMiniFilterResponseSerial;
        const auto again = [this, sliceId]() { requestMiniFilterResponse(sliceId); };
        state.connections << connect(slice, &SliceModel::filterChanged, this, again)
                          << connect(slice, &SliceModel::dspModeChanged, this, again)
                          << connect(slice, &SliceModel::minNotchWidthHzChanged, this, again)
                          << connect(slice, &SliceModel::streamIndexChanged, this, again);
        requestMiniFilterResponse(sliceId);
        if (!self) { return; }
        if (m_miniFilterDemandSetEpoch != setEpoch) { return; }
    }
}

RadioModel::FilterResponse RadioModel::miniFilterResponse(int sliceId) const
{
    const auto found = m_miniFilterResponses.constFind(sliceId);
    return found == m_miniFilterResponses.cend() ? FilterResponse{} : found->response;
}

void RadioModel::requestMiniFilterResponse(int sliceId)
{
    auto found = m_miniFilterResponses.find(sliceId);
    if (found == m_miniFilterResponses.end()) { return; }
    const QPointer<RadioModel> self(this);
    const quint64 serial = found->serial;
    found->response = {};
    emit miniFilterResponseChanged(sliceId);
    if (!self) { return; }
    found = m_miniFilterResponses.find(sliceId);
    if (found == m_miniFilterResponses.end() || found->serial != serial) { return; }
    if (found->command != 0) { found->dirty = true; return; }
    if (m_role != Role::Remote || !m_station || m_stationDspInfoVersion < 1
        || !sliceById(sliceId)) { return; }
    const IStationLink::CommandOutcome outcome =
        m_station->requestFilterResponse(sliceId, /*highResolution=*/true);
    if (!self) { return; }
    found = m_miniFilterResponses.find(sliceId);
    if (found == m_miniFilterResponses.end() || found->serial != serial) { return; }
    if (outcome.sent) {
        found->command = outcome.commandId != 0 ? outcome.commandId : 1;
        found->dirty = false;
    }
}

void RadioModel::reportStationFilterResponse(quint32 commandId, bool accepted,
                                             const QString& reason, double startHz,
                                             double stepHz, const QString& json)
{
    Q_UNUSED(reason);
    const QPointer<RadioModel> self(this);
    for (int sliceId : m_miniFilterResponses.keys()) {
        auto it = m_miniFilterResponses.find(sliceId);
        if (it == m_miniFilterResponses.end() || it->command != commandId
            || it->command == 0) { continue; }
        const quint64 serial = it->serial;
        const bool again = it->dirty;
        it->command = 0;
        it->dirty = false;
        FilterResponse response;
        if (accepted) {
            const auto values = filterResponseFromJson(json);
            if (values && std::isfinite(startHz) && std::isfinite(stepHz)
                && stepHz > 0.0) {
                response.startHz = startHz;
                response.stepHz = stepHz;
                response.magnitudesDb = *values;
            }
        }
        it->response = std::move(response);
        emit miniFilterResponseChanged(sliceId);
        if (!self) { return; }
        it = m_miniFilterResponses.find(sliceId);
        if (again && it != m_miniFilterResponses.end() && it->serial == serial) {
            requestMiniFilterResponse(sliceId);
        }
        return;
    }
    if (m_coreFilterResponseCommand == 0 || commandId != m_coreFilterResponseCommand) {
        return;
    }
    m_coreFilterResponseCommand = 0;
    if (accepted) {
        const std::optional<QVector<double>> values = filterResponseFromJson(json);
        FilterResponse response;
        if (values && std::isfinite(startHz) && std::isfinite(stepHz) && stepHz >= 0.0) {
            response.startHz = startHz;
            response.stepHz = stepHz;
            response.magnitudesDb = *values;
        }
        m_coreFilterResponse = response;
    } else {
        // No curve to draw (no receiver yet): the graph shows its passband.
        m_coreFilterResponse = FilterResponse{};
    }
    emit coreFilterResponseChanged();
    if (!self) { return; }
    if (m_coreFilterResponseDirty) {
        requestCoreFilterResponse();
    }
}

void RadioModel::failStationFilterResponse()
{
    // The link closed: the curve request it held gets no answer, so the
    // next session asks afresh (setStationDspInfoVersion).
    m_coreFilterResponseCommand = 0;
    m_coreFilterResponseDirty = false;
    const QPointer<RadioModel> self(this);
    QVector<QPair<int, quint64>> failedDemands;
    failedDemands.reserve(m_miniFilterResponses.size());
    for (auto it = m_miniFilterResponses.cbegin(); it != m_miniFilterResponses.cend(); ++it) {
        failedDemands.append({it.key(), it->serial});
    }
    for (const auto& [sliceId, serial] : failedDemands) {
        auto it = m_miniFilterResponses.find(sliceId);
        if (it == m_miniFilterResponses.end() || it->serial != serial) { continue; }
        it->command = 0;
        it->dirty = false;
        it->response = {};
        emit miniFilterResponseChanged(sliceId);
        if (!self) { return; }
    }
}

void RadioModel::refreshSliceMinNotchWidths()
{
    if (m_role == Role::Remote) {
        return;
    }
    // Each slice carries its own receiver's minimum (as the local TNF page
    // reads RxChannel::minNotchWidthHz), 0 while it has no channel. The
    // channel's own signal re-runs this when a filter size or rate moves it
    // (console.cs:48787-48818 UpdateMinimumNotchWidthRX [v2.10.3.15] is the
    // same re-read in Thetis).
    for (SliceModel* slice : m_slices) {
        RxChannel* channel = rxChannelForSlice(slice->sliceIndex());
        if (channel == nullptr) {
            slice->setMinNotchWidthHz(0.0);
            continue;
        }
        connect(channel, &RxChannel::minNotchWidthChanged, this,
                &RadioModel::refreshSliceMinNotchWidths, Qt::UniqueConnection);
        slice->setMinNotchWidthHz(channel->minNotchWidthHz());
    }
}

bool RadioModel::applyMeterSetting(const QString& key, const QVariant& value)
{
    if (key != QLatin1String("MultimeterDelayMs") || m_sliceMeterPump == nullptr) {
        return false;
    }
    // From Thetis setup.cs:8148-8151 [v2.10.3.15]:
    //   private void udDisplayMeterDelay_ValueChanged(object sender, System.EventArgs e)
    //   {
    //       if (initializing) return;
    //       console.MeterDelay = (int)udDisplayMeterDelay.Value;
    // The pump clamps (SliceMeterPump::setIntervalMs); 100 is the key's
    // default, as the pump's constructor reads it.
    bool ok = false;
    const int ms = value.isValid() ? value.toString().toInt(&ok) : 100;
    m_sliceMeterPump->setIntervalMs(value.isValid() && !ok ? 100 : ms);
    return true;
}

void RadioModel::applyRemoteTxDisplaySetting(const QString& key)
{
    // Parity Task 30: Thetis's TX Display handlers set the transmit
    // analyzer at once and check nothing about MOX; reloadSetting carries
    // the cite.
    if (m_txAnalyzer == nullptr || !TxAnalyzer::isSettingsKey(key)) {
        return;
    }
    m_txAnalyzer->reloadSetting(key);
}

