// The HL2 options a Hermes Lite 2 takes on the wire, pushed whole to the
// P1 connection on its own thread (each setter is idempotent):
//   Band Volts and Disable PS Sync, bank 0 C3 bits 3 and 4
//     From mi0bot Console/setup.cs:2843-2848, 13376-13390 [@c26a8a4]:
//       chkHL2BandVolts_CheckedChanged(this, e);        // MI0BOT: HL2 option page now doesn't share ditter and random
//       // MI0BOT: Control band volts for the HL2
//       // MI0BOT: Control power supply sync for the HL2
//   TX buffer latency and PTT hang, bank 17 C4 and C3
//     From mi0bot Console/setup.cs:21236-21248 [@c26a8a4]:
//       // MI0BOT: Controls the hardware tx buffer in the HL2
//       // MI0BOT: Controls the hardware PTT hang in the HL2
//   Reset on Ethernet disconnect, bank 18 C4
//     From mi0bot Console/setup.cs:21257-21262 [@c26a8a4]:
//       // MI0BOT: Controls if the HL2 will reset after an Ethernet disconnect
//   External 10 MHz, Enable CL2 and CL2 frequency, the clock chip over I2C
//   (P1RadioConnection::setHl2Clock)
//     From mi0bot Console/setup.cs:21732-21756 [@c26a8a4]:
//       // MI0BOT: Support for HL2 Cl2 clock output
//       // MI0BOT: Support for HL2 10MHz clock input
void RadioModel::connectHl2OptionsToConnection()
{
    // applyHl2Options reads the options and m_connection, both on the main
    // thread, so the watch runs here (context this) and only the setters
    // cross to the connection's thread. One watch at a time: a reconnect
    // replaces it.
    QObject::disconnect(m_hl2OptionsConnection);
    if (qobject_cast<P1RadioConnection*>(m_connection) != nullptr) {
        applyHl2Options();
        m_hl2OptionsConnection = connect(&m_hl2Options, &Hl2OptionsModel::changed, this,
                                         [this]() { applyHl2Options(); });
    }
}

void RadioModel::applyHl2Options()
{
    auto* p1 = qobject_cast<P1RadioConnection*>(m_connection);
    if (p1 == nullptr) {
        return;
    }
    const bool bandVolts = m_hl2Options.bandVolts();
    const bool psSync = m_hl2Options.psSync();
    const int txLatencyMs = m_hl2Options.txLatencyMs();
    const int pttHangMs = m_hl2Options.pttHangMs();
    const bool resetOnDisconnect = m_hl2Options.disconnectReset();
    const bool ext10MHz = m_hl2Options.ext10MHz();
    const bool cl2Enabled = m_hl2Options.cl2Enabled();
    const int cl2FreqKHz = m_hl2Options.cl2FreqKHz();
    // Radio codec (2026-09-30): Swap audio channels, mi0bot
    // setup.cs:38065 chkSwapAudioChannels [@c26a8a4].
    const bool swapAudio = m_hl2Options.swapAudioChannels();
    QMetaObject::invokeMethod(p1, [p1, bandVolts, psSync, txLatencyMs, pttHangMs,
                                   resetOnDisconnect, ext10MHz, cl2Enabled, cl2FreqKHz,
                                   swapAudio]() {
        p1->setHl2BandVolts(bandVolts);
        p1->setHl2PsSync(psSync);
        p1->setHl2TxLatency(txLatencyMs);
        p1->setHl2PttHang(pttHangMs);
        p1->setHl2ResetOnDisconnect(resetOnDisconnect);
        p1->setHl2Clock(ext10MHz, cl2Enabled, cl2FreqKHz);
        p1->setHl2SwapAudioChannels(swapAudio);
    });
}

void RadioModel::applyDisableHfPaSetting()
{
    applyDisableHfPaSetting(AppSettings::instance().value(QLatin1String(kDisableHfPaKey)));
}

void RadioModel::applyDisableHfPaSetting(const QVariant& value)
{
    if (!ownsLocalDsp()) {
        return;
    }
    // Default off: console.cs:10891 [v2.10.3.15] hf_tr_relay = false.
    const bool saved = value.isValid() && value.toString() == QStringLiteral("True");
    // Thetis unchecks the box on a radio that does not offer it
    // (setup.cs:6325), so there it is off whatever was saved; the saved
    // value is kept for a radio that does.
    const bool disabled = saved && hfPaSwitchAvailable(m_hardwareProfile.model);
    m_swrProt.setHfPaDisabled(disabled);
    if (m_connection == nullptr) {
        return;
    }
    RadioConnection* conn = m_connection;
    QMetaObject::invokeMethod(conn, [conn, disabled]() {
        conn->setPaDisabled(disabled);
    });
}

